window.__qzParts=window.__qzParts||{};window.__qzParts.khtn=[{"p":"Khoa học tự nhiên là môn học nghiên cứu về điều gì?","o":["Các sự vật, hiện tượng của thế giới tự nhiên và cách chúng vận động, biến đổi","Các con số và những phép tính trong toán học","Lịch sử các triều đại phong kiến xưa","Cách viết văn và làm thơ cho hay"],"a":"Các sự vật, hiện tượng của thế giới tự nhiên và cách chúng vận động, biến đổi","h":"Hãy chú ý đến chính tên gọi của môn học, nó gắn với thế giới xung quanh ta.","e":"Khoa học tự nhiên nghiên cứu các sự vật, hiện tượng trong tự nhiên như chất, năng lượng, vật sống và Trái Đất.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Để đo chiều dài của một quyển sách, em nên dùng dụng cụ nào sau đây?","o":["Cân đồng hồ","Thước (thước kẻ, thước mét)","Đồng hồ bấm giây","Nhiệt kế"],"a":"Thước (thước kẻ, thước mét)","h":"Chiều dài được đo bằng dụng cụ có chia vạch theo đơn vị độ dài.","e":"Thước dùng để đo độ dài; cân đo khối lượng, đồng hồ đo thời gian và nhiệt kế đo nhiệt độ.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trong hệ đo lường quốc tế, đơn vị đo khối lượng chuẩn là gì?","o":["Mét (m)","Giây (s)","Kilôgam (kg)","Lít (l)"],"a":"Kilôgam (kg)","h":"Khối lượng của một vật cho biết lượng chất của vật đó.","e":"Kilôgam (kg) là đơn vị đo khối lượng chuẩn; mét đo độ dài, giây đo thời gian và lít đo thể tích.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Kính hiển vi được dùng để làm gì?","o":["Quan sát các ngôi sao ở rất xa","Đo nhiệt độ của một vật","Nghe những âm thanh rất nhỏ","Quan sát những vật rất nhỏ mà mắt thường không nhìn thấy được, như vi khuẩn hay tế bào"],"a":"Quan sát những vật rất nhỏ mà mắt thường không nhìn thấy được, như vi khuẩn hay tế bào","h":"Kính hiển vi giúp ta nhìn rõ những vật có kích thước vô cùng bé.","e":"Kính hiển vi phóng đại hình ảnh của các vật rất nhỏ như vi khuẩn, tế bào mà mắt thường không thấy được.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi làm việc trong phòng thực hành, việc làm nào sau đây KHÔNG được phép?","o":["Tự ý nếm hoặc ngửi trực tiếp hoá chất trong lọ","Đeo kính bảo hộ khi thầy cô yêu cầu","Rửa tay sạch sau khi thực hành","Làm thí nghiệm đúng theo hướng dẫn của thầy cô"],"a":"Tự ý nếm hoặc ngửi trực tiếp hoá chất trong lọ","h":"Hãy nghĩ đến những việc có thể gây nguy hiểm cho chính em.","e":"Hoá chất có thể độc hại nên tuyệt đối không nếm, không ngửi trực tiếp; cần tuân thủ các quy định an toàn trong phòng thực hành.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Chất thường tồn tại ở ba thể nào?","o":["Thể rắn, thể lỏng và ánh sáng","Thể rắn, thể lỏng và thể khí","Thể lỏng, thể khí và âm thanh","Thể rắn, thể khí và điện"],"a":"Thể rắn, thể lỏng và thể khí","h":"Hãy nhớ đến nước đá, nước lỏng và hơi nước quen thuộc.","e":"Mọi chất thường tồn tại ở ba thể: rắn, lỏng và khí, ví dụ nước đá, nước lỏng và hơi nước.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Chất ở thể rắn có đặc điểm nào sau đây?","o":["Có thể tích xác định nhưng không có hình dạng riêng","Không có hình dạng và thể tích xác định","Có hình dạng và thể tích xác định","Luôn chiếm đầy toàn bộ không gian chứa nó"],"a":"Có hình dạng và thể tích xác định","h":"Hãy hình dung một viên gạch hoặc một hòn đá đặt ở đâu cũng không đổi hình dạng.","e":"Chất ở thể rắn có hình dạng và thể tích xác định; thể lỏng chỉ có thể tích xác định, còn thể khí không có cả hai.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Nước đá để ngoài trời nắng dần tan thành nước lỏng. Hiện tượng này gọi là gì?","o":["Sự đông đặc","Sự bay hơi","Sự ngưng tụ","Sự nóng chảy"],"a":"Sự nóng chảy","h":"Đây là quá trình chất chuyển từ thể rắn sang thể lỏng.","e":"Nóng chảy là quá trình chất chuyển từ thể rắn sang thể lỏng, như nước đá tan thành nước.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Quần áo ướt phơi ngoài nắng một lúc sẽ khô. Nước trong quần áo đã xảy ra hiện tượng gì?","o":["Bay hơi","Ngưng tụ","Đông đặc","Nóng chảy"],"a":"Bay hơi","h":"Nước lỏng đã biến đi đâu khi quần áo khô?","e":"Bay hơi là quá trình nước lỏng chuyển thành hơi nước, làm quần áo ướt dần khô đi.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vào sáng sớm, trên lá cây thường có những giọt nước nhỏ dù trời không mưa. Những giọt nước này hình thành do hơi nước trong không khí đã","o":["bay hơi thành hơi nước","ngưng tụ thành nước lỏng","đông đặc thành băng","nóng chảy thành nước"],"a":"ngưng tụ thành nước lỏng","h":"Hơi nước gặp lạnh sẽ biến thành giọt nước lỏng bám trên lá.","e":"Ngưng tụ là quá trình hơi nước chuyển thành nước lỏng; sương đọng trên lá cây vào sáng sớm là ví dụ quen thuộc.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Hiện tượng nào sau đây cho thấy tính chất hoá học của chất?","o":["Nước sôi ở 100 độ C","Thuỷ tinh trong suốt và dễ vỡ","Sắt để lâu trong không khí ẩm bị gỉ","Dây đồng dẫn điện tốt"],"a":"Sắt để lâu trong không khí ẩm bị gỉ","h":"Tính chất hoá học gắn với khả năng chất biến đổi thành chất khác.","e":"Sắt bị gỉ là sự biến đổi sắt thành chất mới nên thuộc tính chất hoá học; sôi, trong suốt, dẫn điện là tính chất vật lí.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Khí oxygen chiếm khoảng bao nhiêu phần trăm thể tích của không khí?","o":["Khoảng 1%","Khoảng 50%","Khoảng 78%","Khoảng 21%"],"a":"Khoảng 21%","h":"Khí chiếm nhiều nhất trong không khí là nitrogen, oxygen đứng thứ hai.","e":"Không khí gồm khoảng 78% nitrogen, khoảng 21% oxygen và khoảng 1% các khí khác.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khí oxygen rất cần thiết cho đời sống vì nó","o":["duy trì sự cháy và cần cho hô hấp của người, động vật","giúp nước đóng băng nhanh hơn","giúp mọi cây cối ra hoa cùng lúc","làm cho kim loại cứng hơn"],"a":"duy trì sự cháy và cần cho hô hấp của người, động vật","h":"Hãy nhớ ngọn nến sẽ tắt khi bị đậy kín và con người cần hít thở liên tục.","e":"Oxygen duy trì sự cháy và là khí cần thiết cho hô hấp của người và động vật.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Có một hỗn hợp gồm bột sắt trộn lẫn với cát. Cách tách bột sắt ra khỏi cát đơn giản nhất là","o":["lọc hỗn hợp bằng giấy lọc","dùng nam châm đưa lại gần để hút bột sắt","đun nóng cho hỗn hợp bay hơi hết","đổ bỏ phần trên mặt của hỗn hợp"],"a":"dùng nam châm đưa lại gần để hút bột sắt","h":"Hãy nhớ tính chất đặc biệt của sắt khi gặp nam châm.","e":"Nam châm hút được sắt nên dùng nam châm là cách đơn giản và hiệu quả nhất để tách bột sắt khỏi cát.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Lốp xe thường được làm bằng cao su vì cao su có tính chất nổi bật nào?","o":["Dẫn điện rất tốt","Trong suốt như thuỷ tinh","Đàn hồi tốt, ma sát lớn và không thấm nước","Nhẹ hơn không khí"],"a":"Đàn hồi tốt, ma sát lớn và không thấm nước","h":"Lốp xe cần bám đường tốt và chịu được biến dạng khi xe chạy.","e":"Cao su đàn hồi, có ma sát lớn giúp xe bám đường và không thấm nước nên được dùng làm lốp xe, ủng đi mưa.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Lực là gì?","o":["Một dạng năng lượng chứa trong vật","Khả năng chạy nhanh của một vật","Sự chuyển động của một vật","Tác dụng đẩy hoặc kéo của vật này lên vật khác"],"a":"Tác dụng đẩy hoặc kéo của vật này lên vật khác","h":"Khi em đẩy xe hay kéo ngăn bàn, em đang tác dụng điều gì lên vật?","e":"Lực là tác dụng đẩy hoặc kéo của vật này lên vật khác, ví dụ tay đẩy xe, tay kéo dây.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trường hợp nào sau đây là lực không tiếp xúc?","o":["Nam châm hút chiếc đinh sắt dù chưa chạm vào đinh","Tay đẩy chiếc xe đạp","Chân đá quả bóng","Hai bạn kéo co bằng dây"],"a":"Nam châm hút chiếc đinh sắt dù chưa chạm vào đinh","h":"Lực không tiếp xúc xảy ra khi vật tác dụng lực mà không chạm vào vật kia.","e":"Nam châm hút đinh sắt từ xa nên đó là lực không tiếp xúc; các trường hợp còn lại đều có sự chạm trực tiếp.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trọng lực là gì?","o":["Lực đẩy của nước tác dụng lên vật","Lực hút của Trái Đất tác dụng lên mọi vật","Lực hút giữa hai cực của nam châm","Lực thổi của gió lên mọi vật"],"a":"Lực hút của Trái Đất tác dụng lên mọi vật","h":"Nhờ lực này mà mọi vật rơi xuống đều hướng về mặt đất.","e":"Trọng lực là lực hút của Trái Đất tác dụng lên mọi vật, kéo mọi vật về phía mặt đất.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Lực tác dụng lên một vật có thể gây ra kết quả nào?","o":["Chỉ làm vật nóng lên","Chỉ làm vật đổi màu","Làm vật thay đổi chuyển động hoặc biến dạng, hoặc cả hai","Làm vật biến mất hoàn toàn"],"a":"Làm vật thay đổi chuyển động hoặc biến dạng, hoặc cả hai","h":"Hãy nghĩ khi em đá bóng đứng yên và khi em bóp một quả bóng cao su.","e":"Lực có thể làm vật đang đứng yên chuyển động, chuyển động nhanh hay chậm lại, hoặc làm vật biến dạng.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Trường hợp nào sau đây lực ma sát có ích?","o":["Ma sát làm đế giày bị mòn dần","Ma sát làm các chi tiết máy bị mòn và nóng lên","Ma sát làm xích xe đạp bị mòn","Ma sát giữa lốp xe và mặt đường giúp xe bám đường, không bị trượt"],"a":"Ma sát giữa lốp xe và mặt đường giúp xe bám đường, không bị trượt","h":"Ma sát có ích khi nó giúp chuyển động được an toàn và thuận lợi.","e":"Ma sát giữa lốp xe và mặt đường giúp xe bám đường; còn ma sát làm mòn vật là ma sát có hại.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trường hợp nào sau đây lực ma sát có hại?","o":["Ma sát giữa các bộ phận chuyển động trong máy làm chúng bị mòn và nóng lên","Ma sát giữa tay và cán vợt giúp cầm chắc vợt","Ma sát giữa đế giày và mặt đường giúp ta đi không trượt","Ma sát giữa phấn và bảng giúp viết được chữ"],"a":"Ma sát giữa các bộ phận chuyển động trong máy làm chúng bị mòn và nóng lên","h":"Ma sát có hại khi nó gây mòn, nóng và cản trở hoạt động của máy móc.","e":"Ma sát giữa các chi tiết máy làm chúng mòn và nóng lên nên người ta phải tra dầu mỡ để giảm ma sát có hại này.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Khi ta kéo giãn một lò xo rồi buông tay ra, lò xo trở lại hình dạng ban đầu nhờ có","o":["lực ma sát","lực đàn hồi","trọng lực","lực hút của nam châm"],"a":"lực đàn hồi","h":"Đây là loại lực xuất hiện khi vật bị biến dạng như lò xo, dây cao su.","e":"Khi lò xo bị kéo giãn hoặc nén, nó sinh ra lực đàn hồi kéo lò xo trở về hình dạng ban đầu.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vật nào sau đây phát ra năng lượng ánh sáng?","o":["Cục pin chưa sử dụng","Ấm nước vừa đun sôi","Bóng đèn đang sáng","Quyển sách để trên bàn"],"a":"Bóng đèn đang sáng","h":"Năng lượng ánh sáng còn gọi là quang năng, giúp ta nhìn thấy vật.","e":"Bóng đèn đang sáng phát ra năng lượng ánh sáng; pin chứa hoá năng, ấm nước nóng chứa nhiệt năng.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vật nào sau đây có động năng?","o":["Chiếc xe đạp dựng yên trong sân","Quyển sách nằm yên trên bàn","Hòn đá nằm yên trên mặt đất","Chiếc xe đạp đang chạy trên đường"],"a":"Chiếc xe đạp đang chạy trên đường","h":"Động năng là năng lượng của vật đang chuyển động.","e":"Vật đang chuyển động thì có động năng, như xe đạp đang chạy; các vật đứng yên không có động năng.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi quạt điện hoạt động, năng lượng điện đã chuyển hoá chủ yếu thành dạng năng lượng nào?","o":["Động năng của cánh quạt (kèm một phần nhiệt năng)","Quang năng","Hoá năng","Âm năng"],"a":"Động năng của cánh quạt (kèm một phần nhiệt năng)","h":"Cánh quạt quay được là nhờ dạng năng lượng nào?","e":"Quạt điện biến điện năng thành động năng làm cánh quạt quay, đồng thời một phần nhỏ thành nhiệt năng.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Đèn pin đang sáng dùng pin. Sự chuyển hoá năng lượng trong đèn pin là","o":["động năng chuyển thành điện năng","hoá năng của pin chuyển thành quang năng","quang năng chuyển thành hoá năng","nhiệt năng chuyển thành động năng"],"a":"hoá năng của pin chuyển thành quang năng","h":"Hãy bắt đầu từ nguồn năng lượng dự trữ trong pin.","e":"Pin chứa hoá năng; khi đèn pin sáng, hoá năng của pin chuyển hoá thành năng lượng ánh sáng.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Việc làm nào sau đây giúp tiết kiệm năng lượng?","o":["Bật thật nhiều đèn cho phòng thật sáng","Mở cửa tủ lạnh thật lâu để ngắm đồ ăn","Tắt đèn và quạt khi ra khỏi phòng","Để ti vi chạy suốt ngày dù không ai xem"],"a":"Tắt đèn và quạt khi ra khỏi phòng","h":"Tiết kiệm năng lượng là chỉ dùng năng lượng khi thật cần thiết.","e":"Tắt các thiết bị điện khi không sử dụng giúp tiết kiệm điện năng và bảo vệ môi trường.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Đơn vị cấu tạo cơ bản của mọi cơ thể sống là gì?","o":["Mô","Cơ quan","Hệ cơ quan","Tế bào"],"a":"Tế bào","h":"Cơ thể của em được xây nên từ hàng tỉ đơn vị rất nhỏ.","e":"Tế bào là đơn vị cấu tạo cơ bản của mọi cơ thể sống, từ vi khuẩn đến con người.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Tế bào thực vật khác tế bào động vật ở điểm nào?","o":["Có thành tế bào và lục lạp","Có nhân tế bào","Có màng tế bào","Có chất tế bào"],"a":"Có thành tế bào và lục lạp","h":"Hãy nhớ bộ phận giúp lá cây quang hợp và lớp vỏ cứng bao ngoài tế bào lá.","e":"Tế bào thực vật có thành tế bào và lục lạp để quang hợp, còn tế bào động vật không có hai bộ phận này.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Lục lạp trong tế bào thực vật có vai trò gì?","o":["Giúp cây hô hấp vào ban đêm","Hấp thụ ánh sáng Mặt Trời để cây quang hợp, tạo chất dinh dưỡng","Bảo vệ tế bào khỏi vi khuẩn","Giúp rễ cây hút nước"],"a":"Hấp thụ ánh sáng Mặt Trời để cây quang hợp, tạo chất dinh dưỡng","h":"Lục lạp chứa chất diệp lục làm lá có màu xanh.","e":"Lục lạp chứa diệp lục, hấp thụ ánh sáng để quang hợp, tạo chất dinh dưỡng nuôi cây.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Sinh vật nào sau đây là cơ thể đơn bào?","o":["Con cá vàng","Cây ngô","Trùng roi","Con mèo"],"a":"Trùng roi","h":"Cơ thể đơn bào chỉ gồm đúng một tế bào duy nhất.","e":"Trùng roi, amip là cơ thể đơn bào; cá, cây ngô và mèo là cơ thể đa bào gồm rất nhiều tế bào.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Thứ tự đúng của các cấp độ tổ chức trong cơ thể đa bào từ nhỏ đến lớn là","o":["Mô tạo thành tế bào, tế bào tạo thành cơ quan, cơ quan tạo thành cơ thể","Cơ quan tạo thành mô, mô tạo thành tế bào, tế bào tạo thành cơ thể","Tế bào tạo thành cơ quan, cơ quan tạo thành mô, mô tạo thành cơ thể","Tế bào tạo thành mô, mô tạo thành cơ quan, cơ quan tạo thành hệ cơ quan, hệ cơ quan tạo thành cơ thể"],"a":"Tế bào tạo thành mô, mô tạo thành cơ quan, cơ quan tạo thành hệ cơ quan, hệ cơ quan tạo thành cơ thể","h":"Hãy bắt đầu từ đơn vị nhỏ nhất là tế bào và xếp dần lên.","e":"Các cấp độ tổ chức trong cơ thể đa bào đi từ tế bào lên mô, cơ quan, hệ cơ quan rồi đến cơ thể hoàn chỉnh.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Nhiều cơ quan cùng phối hợp thực hiện một chức năng sống thì tạo thành","o":["hệ cơ quan","mô","tế bào","cơ thể đơn bào"],"a":"hệ cơ quan","h":"Ví dụ tim và các mạch máu cùng làm nhiệm vụ vận chuyển máu.","e":"Tập hợp các cơ quan cùng phối hợp thực hiện một chức năng sống gọi là hệ cơ quan, như hệ tuần hoàn gồm tim và mạch máu.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Nhận định nào đúng về vi khuẩn?","o":["Vi khuẩn chưa có cấu tạo tế bào","Vi khuẩn là sinh vật có cấu tạo tế bào, kích thước rất nhỏ, phải dùng kính hiển vi mới thấy","Vi khuẩn nhìn thấy rõ bằng mắt thường","Tất cả vi khuẩn đều gây bệnh cho người"],"a":"Vi khuẩn là sinh vật có cấu tạo tế bào, kích thước rất nhỏ, phải dùng kính hiển vi mới thấy","h":"Vi khuẩn nhỏ đến mức cần dụng cụ phóng đại mới quan sát được.","e":"Vi khuẩn là sinh vật có cấu tạo tế bào và kích thước rất nhỏ; có vi khuẩn có hại nhưng cũng có nhiều vi khuẩn có ích.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Virus khác vi khuẩn ở điểm cơ bản nào?","o":["Virus luôn lớn hơn vi khuẩn","Virus tự di chuyển được như động vật","Virus chưa có cấu tạo tế bào hoàn chỉnh, còn vi khuẩn là sinh vật có tế bào","Virus là sinh vật đa bào"],"a":"Virus chưa có cấu tạo tế bào hoàn chỉnh, còn vi khuẩn là sinh vật có tế bào","h":"Đây là lí do virus không được coi là sinh vật có cấu tạo tế bào.","e":"Vi khuẩn là sinh vật đơn bào, còn virus chưa có cấu tạo tế bào hoàn chỉnh và chỉ nhân lên được khi ở trong tế bào của vật chủ.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Con người đã lợi dụng vi khuẩn có ích để làm việc nào sau đây?","o":["Gây bệnh tả cho người","Làm thức ăn bị ôi thiu","Gây sâu răng cho trẻ em","Lên men làm sữa chua, muối dưa, muối cà"],"a":"Lên men làm sữa chua, muối dưa, muối cà","h":"Hãy nhớ món sữa chua em vẫn ăn hằng ngày.","e":"Nhiều vi khuẩn có ích được dùng để lên men làm sữa chua, muối dưa cà; một số vi khuẩn khác mới gây bệnh.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Tính từ Mặt Trời ra xa, Trái Đất là hành tinh thứ mấy trong Hệ Mặt Trời?","o":["Hành tinh thứ ba","Hành tinh thứ nhất","Hành tinh thứ hai","Hành tinh thứ năm"],"a":"Hành tinh thứ ba","h":"Trước Trái Đất là Thuỷ tinh và Kim tinh.","e":"Thứ tự từ Mặt Trời là: Thuỷ tinh, Kim tinh, Trái Đất..., nên Trái Đất là hành tinh thứ ba trong Hệ Mặt Trời.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Hiện tượng ngày và đêm trên Trái Đất là do","o":["Mặt Trăng quay quanh Trái Đất","Trái Đất tự quay quanh trục của nó","Trái Đất chuyển động quanh Mặt Trời","Mặt Trời quay quanh Trái Đất"],"a":"Trái Đất tự quay quanh trục của nó","h":"Khi một nửa Trái Đất hướng về Mặt Trời thì nửa kia chìm trong bóng tối.","e":"Trái Đất tự quay quanh trục nên nơi được Mặt Trời chiếu sáng là ban ngày, nơi khuất sáng là ban đêm.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trái Đất chuyển động quanh Mặt Trời gây ra hiện tượng nào?","o":["Ngày và đêm","Mặt Trăng tròn và khuyết","Các mùa trong năm","Thuỷ triều lên xuống"],"a":"Các mùa trong năm","h":"Hành trình một vòng quanh Mặt Trời của Trái Đất kéo dài một năm.","e":"Trái Đất chuyển động quanh Mặt Trời kết hợp với trục quay nghiêng gây ra các mùa xuân, hạ, thu, đông trong năm.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Mặt Trăng là vệ tinh tự nhiên của Trái Đất. Mặt Trăng sáng được là do","o":["nó tự phát sáng như Mặt Trời","nó được thắp sáng bằng điện","nó phản chiếu ánh sáng của các ngôi sao","nó phản chiếu ánh sáng của Mặt Trời"],"a":"nó phản chiếu ánh sáng của Mặt Trời","h":"Bản thân Mặt Trăng không phải là một nguồn sáng.","e":"Mặt Trăng không tự phát sáng mà phản chiếu ánh sáng Mặt Trời chiếu tới nên ta thấy nó sáng trên bầu trời đêm.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Mẹ vo gạo xong, nước vo gạo có lẫn trấu và sạn nhỏ. Mẹ đổ nước qua một cái rây, trấu và sạn bị giữ lại còn nước chảy qua. Cách tách chất này gọi là phương pháp gì?","o":["Phương pháp lọc","Phương pháp bay hơi","Phương pháp dùng nam châm","Phương pháp đun sôi"],"a":"Phương pháp lọc","h":"Chất rắn không tan bị giữ lại trên vật lọc, chất lỏng chảy qua.","e":"Lọc là cách tách chất rắn không tan ra khỏi chất lỏng nhờ giấy lọc, vải hoặc rây: chất rắn (cát, trấu, sạn) bị giữ lại, nước chảy qua.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Người dân vùng biển đưa nước biển vào ruộng muối rồi phơi dưới nắng gắt nhiều ngày để thu được muối ăn. Họ đã dùng phương pháp tách chất nào?","o":["Phương pháp lọc","Phương pháp bay hơi","Phương pháp dùng nam châm","Phương pháp chắt gạn"],"a":"Phương pháp bay hơi","h":"Dưới nắng, phần nước trong nước biển biến đi đâu?","e":"Dưới nắng, nước trong nước biển bay hơi dần, muối ăn tan trong nước còn lại và kết tinh trên ruộng. Đây là phương pháp bay hơi để tách chất tan ra khỏi dung dịch.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Than, củi, xăng, dầu được gọi là nhiên liệu. Nhiên liệu là những chất có đặc điểm nào sau đây?","o":["Không bao giờ cháy được","Chỉ dùng để làm đồ trang trí","Cháy được và khi cháy toả ra nhiều nhiệt","Luôn tồn tại ở thể lỏng"],"a":"Cháy được và khi cháy toả ra nhiều nhiệt","h":"Người ta đốt than, củi để làm gì trong bếp?","e":"Nhiên liệu là chất cháy được và toả nhiều nhiệt khi cháy, ví dụ than, củi, xăng, dầu, khí đốt. Người ta dùng nhiệt đó để nấu ăn, sưởi ấm, chạy máy móc.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Vì sao chúng ta nên phân loại và tái chế chai nhựa, chai thuỷ tinh đã dùng thay vì vứt hết vào thùng rác?","o":["Để trong nhà có nhiều đồ đạc hơn","Vì chai nhựa và chai thuỷ tinh rất hiếm và đắt","Vì tái chế tốn nhiều điện hơn làm mới","Giúp tiết kiệm tài nguyên, giảm rác thải và bảo vệ môi trường"],"a":"Giúp tiết kiệm tài nguyên, giảm rác thải và bảo vệ môi trường","h":"Nhựa vứt xuống sông, biển sẽ gây hại cho điều gì?","e":"Nhựa và thuỷ tinh rất lâu phân huỷ trong tự nhiên. Tái chế chúng giúp tiết kiệm nguyên liệu, giảm lượng rác thải ra sông biển, đất đai, từ đó bảo vệ môi trường.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Để giữ thịt, cá tươi lâu mà không bị ôi thiu, người ta thường để vào ngăn đá tủ lạnh hoặc sấy khô, phơi khô. Cách bảo quản này có tác dụng chính là gì?","o":["Ngăn vi sinh vật gây hỏng thực phẩm phát triển","Làm cho thực phẩm thơm ngon hơn lúc còn tươi","Làm tăng thêm chất dinh dưỡng trong thực phẩm","Làm thực phẩm biến thành chất khác tốt hơn"],"a":"Ngăn vi sinh vật gây hỏng thực phẩm phát triển","h":"Thực phẩm bị ôi thiu là do sinh vật rất nhỏ nào gây ra?","e":"Thực phẩm hỏng do vi sinh vật (vi khuẩn, nấm mốc) sinh sôi trên đó. Đông lạnh làm chúng chậm hoặc ngừng hoạt động, sấy khô lấy đi nước khiến chúng khó sống, nên thực phẩm giữ được lâu hơn.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Một cây con lớn dần thành cây to, một vết xước trên da em cũng lành lại. Đó là nhờ tế bào trong cơ thể có khả năng nào?","o":["Tế bào tự biến mất khi cơ thể lớn lên","Tế bào lớn lên và phân chia tạo ra tế bào mới","Tế bào di chuyển từ cây này sang cây khác","Tế bào chỉ xuất hiện khi cơ thể bị thương"],"a":"Tế bào lớn lên và phân chia tạo ra tế bào mới","h":"Số lượng tế bào trong cơ thể tăng lên nhờ quá trình nào?","e":"Tế bào lớn lên đến một mức nhất định rồi phân chia thành hai tế bào mới. Nhờ sự phân chia liên tục này mà cơ thể sinh trưởng, lớn lên và hàn gắn được các vết thương nhỏ.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Người ta dùng nấm men để làm bánh mì nở xốp, còn nấm mốc thường mọc trên thức ăn để lâu ngày. Trong phân loại sinh vật, nấm thuộc nhóm nào?","o":["Nấm là thực vật vì thường mọc yên một chỗ","Nấm là động vật rất nhỏ","Nấm thuộc một nhóm riêng, không phải thực vật cũng không phải động vật","Nấm không phải là sinh vật sống"],"a":"Nấm thuộc một nhóm riêng, không phải thực vật cũng không phải động vật","h":"Nấm không có lá xanh để quang hợp như cây.","e":"Nấm là một nhóm sinh vật riêng: chúng không có chất diệp lục để quang hợp như thực vật, cũng không di chuyển và ăn như động vật. Nhiều loài nấm có ích (nấm men làm bánh, nấm ăn được), một số gây hỏng thức ăn hoặc gây bệnh.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Khi tập phân loại sinh vật, thầy cô cho em dùng khoá lưỡng phân. Khoá lưỡng phân dùng để làm gì?","o":["Đo chiều dài và cân nặng của sinh vật","Xác định tên của một sinh vật dựa vào từng cặp đặc điểm đối lập","Nuôi sinh vật lớn nhanh hơn","Vẽ lại hình dạng của sinh vật cho đẹp"],"a":"Xác định tên của một sinh vật dựa vào từng cặp đặc điểm đối lập","h":"\"Lưỡng phân\" nghĩa là chia làm hai nhánh đối lập ở mỗi bước.","e":"Khoá lưỡng phân gồm các bước, mỗi bước có hai lựa chọn đối lập về một đặc điểm (ví dụ: có chân / không có chân). Trả lời lần lượt từng bước, em sẽ đi đến đúng tên của sinh vật cần xác định.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Đa dạng sinh học là gì và vì sao con người cần bảo vệ nó?","o":["Là sự phong phú của các loài sinh vật trong tự nhiên; nếu nhiều loài biến mất, cân bằng tự nhiên sẽ bị phá vỡ","Là số lượng cây xanh trong một công viên","Là sự đa dạng của các loại đá và đất","Là nhiều loại đồ chơi khác nhau của trẻ em"],"a":"Là sự phong phú của các loài sinh vật trong tự nhiên; nếu nhiều loài biến mất, cân bằng tự nhiên sẽ bị phá vỡ","h":"Các loài sinh vật sống dựa vào nhau trong chuỗi thức ăn.","e":"Đa dạng sinh học là sự phong phú, đa dạng của các loài sinh vật và môi trường sống của chúng. Các loài gắn bó với nhau trong tự nhiên, nên mất đi một loài có thể ảnh hưởng đến nhiều loài khác và đến chính con người.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Khi xuống nước bơi, em thấy bước đi và chạy trong nước khó hơn nhiều so với trên bờ. Nguyên nhân chính là gì?","o":["Nước nhẹ hơn không khí nên khó bám chân","Lực cản của nước lớn hơn lực cản của không khí","Trong nước không có trọng lực tác dụng","Nước trong suốt làm em nhìn không rõ đường"],"a":"Lực cản của nước lớn hơn lực cản của không khí","h":"Môi trường nào đặc hơn sẽ cản chuyển động mạnh hơn?","e":"Khi chuyển động, vật phải chịu lực cản của môi trường xung quanh. Nước đặc hơn không khí nhiều nên lực cản của nước lớn hơn hẳn lực cản của không khí, làm ta di chuyển trong nước khó khăn hơn.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Nhóm nguồn năng lượng nào sau đây đều là năng lượng tái tạo, tức là lấy từ nguồn gần như không bao giờ cạn kiệt?","o":["Than đá và dầu mỏ dưới lòng đất","Khí đốt và xăng","Ánh sáng mặt trời, gió và nước chảy","Pin dùng một lần rồi bỏ"],"a":"Ánh sáng mặt trời, gió và nước chảy","h":"Nguồn nào mỗi ngày đều có lại mà không cần đào lên từ lòng đất?","e":"Năng lượng mặt trời, gió và nước là năng lượng tái tạo vì nguồn của chúng liên tục được bổ sung trong tự nhiên, không cạn kiệt như than đá, dầu mỏ. Khi dùng năng lượng, một phần bị biến thành dạng khó dùng lại (như nhiệt toả ra môi trường) gọi là năng lượng hao phí.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Vào đêm trời quang, em có thể thấy một dải sáng mờ vắt ngang bầu trời, đó là Ngân Hà. Hệ Mặt Trời của chúng ta nằm ở đâu so với Ngân Hà?","o":["Nằm hoàn toàn ngoài Ngân Hà","Không liên quan gì đến Ngân Hà","Nằm ở chính giữa của vũ trụ","Nằm trong Ngân Hà — Ngân Hà là dải thiên hà chứa Hệ Mặt Trời"],"a":"Nằm trong Ngân Hà — Ngân Hà là dải thiên hà chứa Hệ Mặt Trời","h":"Dải sáng đó gồm hàng trăm tỉ ngôi sao, Mặt Trời chỉ là một trong số đó.","e":"Ngân Hà là thiên hà chứa Hệ Mặt Trời của chúng ta, gồm hàng trăm tỉ ngôi sao. Nhìn từ Trái Đất, Ngân Hà hiện ra như một dải sáng mờ vắt ngang bầu trời đêm.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Mỗi ngày, ta thấy Mặt Trời mọc ở hướng Đông và lặn ở hướng Tây. Giải thích đúng cho hiện tượng này là:","o":["Mặt Trời thật sự quay xung quanh Trái Đất","Do Mặt Trăng đẩy Mặt Trời di chuyển trên bầu trời","Đó là chuyển động nhìn thấy: Trái Đất tự quay quanh trục nên ta thấy Mặt Trời như di chuyển từ Đông sang Tây","Mặt Trời tự di chuyển ngang qua bầu trời mỗi ngày"],"a":"Đó là chuyển động nhìn thấy: Trái Đất tự quay quanh trục nên ta thấy Mặt Trời như di chuyển từ Đông sang Tây","h":"Giống như ngồi trên xe đang chạy, em thấy cây bên đường như chạy ngược lại.","e":"Trái Đất tự quay quanh trục của nó từ Tây sang Đông. Vì ta đứng trên Trái Đất đang quay nên thấy Mặt Trời như mọc ở Đông, lặn ở Tây — đó là chuyển động nhìn thấy, không phải Mặt Trời thật sự chạy quanh Trái Đất.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Kính lúp thường được dùng để làm gì?","o":["Đo nhiệt độ của nước đang sôi","Quan sát các vật nhỏ để nhìn rõ chi tiết hơn (như chữ in rất nhỏ, con côn trùng nhỏ)","Quan sát các hành tinh ở rất xa Trái Đất","Quan sát vi khuẩn trong một giọt nước"],"a":"Quan sát các vật nhỏ để nhìn rõ chi tiết hơn (như chữ in rất nhỏ, con côn trùng nhỏ)","h":"Kính lúp phóng đại hình ảnh của vật lên vài lần, cầm tay sử dụng.","e":"Kính lúp là một thấu kính hội tụ cầm tay, giúp phóng đại hình ảnh của các vật nhỏ như chữ in nhỏ, tem thư, côn trùng nhỏ. Quan sát hành tinh dùng kính thiên văn, còn quan sát vi khuẩn phải dùng kính hiển vi.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Để đo chính xác thời gian một bạn chạy 100 m trong giờ thể dục, em nên dùng dụng cụ nào?","o":["Đồng hồ đeo tay thông thường","Đồng hồ cát","Đồng hồ bấm giây","Nhiệt kế"],"a":"Đồng hồ bấm giây","h":"Cần dụng cụ bấm bắt đầu và dừng đúng lúc, đo được cả phần mười giây.","e":"Đồng hồ bấm giây cho phép bấm bắt đầu và dừng đúng thời điểm, đo được khoảng thời gian ngắn chính xác đến 0,1 giây, nên được dùng để đo thời gian chạy, thời gian làm thí nghiệm.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Nhiệt kế chất lỏng (như nhiệt kế rượu màu đỏ) đo được nhiệt độ là nhờ hiện tượng nào?","o":["Chất lỏng bay hơi khi gặp nóng","Chất lỏng nở ra khi nóng lên và co lại khi lạnh đi","Chất lỏng đổi màu khi nhiệt độ thay đổi","Chất lỏng sôi lên khi nhiệt độ tăng"],"a":"Chất lỏng nở ra khi nóng lên và co lại khi lạnh đi","h":"Hãy quan sát cột chất lỏng trong ống nhiệt kế dâng lên hay hạ xuống khi nhiệt độ thay đổi.","e":"Chất lỏng trong nhiệt kế nở ra khi nóng lên (cột chất lỏng dâng cao) và co lại khi lạnh đi (cột chất lỏng hạ xuống). Đọc vị trí cột chất lỏng trên thang chia độ cho ta biết nhiệt độ, thường đo bằng đơn vị độ C (°C).","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Nguyên liệu khác vật liệu ở điểm nào?","o":["Nguyên liệu là vật liệu lấy từ tự nhiên, chưa qua chế biến (như quặng sắt, gỗ trong rừng, dầu mỏ mới khai thác)","Nguyên liệu là chất do con người tổng hợp hoàn toàn trong phòng thí nghiệm","Nguyên liệu chỉ dùng để làm đồ ăn","Nguyên liệu và vật liệu hoàn toàn giống nhau, không khác gì"],"a":"Nguyên liệu là vật liệu lấy từ tự nhiên, chưa qua chế biến (như quặng sắt, gỗ trong rừng, dầu mỏ mới khai thác)","h":"Hãy nghĩ về quặng sắt mới đào từ mỏ và thanh thép đã luyện: cái nào là nguyên liệu?","e":"Nguyên liệu là vật liệu tự nhiên chưa qua chế biến, lấy trực tiếp từ thiên nhiên như quặng, gỗ, dầu mỏ, tre nứa. Qua chế biến (nấu, luyện, xẻ...), nguyên liệu trở thành vật liệu để làm ra sản phẩm.","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Dựa vào cột sống, thế giới động vật được chia thành hai nhóm lớn nào?","o":["Động vật sống trên cạn và động vật sống dưới nước","Động vật ăn thịt và động vật ăn cỏ","Động vật có xương sống và động vật không xương sống","Động vật đẻ trứng và động vật đẻ con"],"a":"Động vật có xương sống và động vật không xương sống","h":"Hãy nghĩ đến con cá, con chim (có cột sống) và con giun đất, con ốc (không có cột sống).","e":"Dựa vào đặc điểm có hay không có cột sống, động vật được chia thành hai nhóm lớn: động vật có xương sống (cá, ếch, chim, thú...) và động vật không xương sống (giun, ốc, sâu bọ, sứa...).","t":"khtn-lop6","g":6,"l":"nhe-nhang"},{"p":"Trong khoa học, một lực được biểu diễn bằng một mũi tên. Mũi tên đó cho ta biết những thông tin gì về lực?","o":["Chỉ cho biết vật nặng hay nhẹ","Gốc mũi tên là điểm đặt lực, hướng mũi tên là hướng của lực, độ dài mũi tên thể hiện độ lớn của lực","Chỉ cho biết vật đang đứng yên hay chuyển động","Cho biết vật làm bằng chất liệu gì"],"a":"Gốc mũi tên là điểm đặt lực, hướng mũi tên là hướng của lực, độ dài mũi tên thể hiện độ lớn của lực","h":"Một lực được xác định bởi ba yếu tố: điểm đặt, phương chiều và độ lớn.","e":"Lực được biểu diễn bằng một mũi tên: gốc của mũi tên đặt tại điểm đặt của lực, mũi tên hướng theo hướng tác dụng của lực và độ dài của mũi tên (theo một tỉ lệ xích chọn trước) thể hiện độ lớn của lực.","t":"khtn-lop6","g":6,"l":"thu-thach"},{"p":"Nguyên tử gồm hai phần chính là:","o":["Hạt nhân nằm ở trung tâm và các electron chuyển động xung quanh hạt nhân","Hạt nhân và các phân tử nước","Các proton chuyển động xung quanh một electron nằm ở trung tâm","Chỉ gồm các electron xếp thành từng lớp"],"a":"Hạt nhân nằm ở trung tâm và các electron chuyển động xung quanh hạt nhân","h":"Hãy nhớ mô hình cấu tạo nguyên tử đã học.","e":"Nguyên tử gồm hạt nhân mang điện tích dương ở trung tâm và các electron mang điện tích âm chuyển động xung quanh hạt nhân.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Hạt nhân nguyên tử được cấu tạo từ các hạt nào?","o":["Proton và electron","Proton và neutron","Electron và neutron","Chỉ gồm các electron"],"a":"Proton và neutron","h":"Hạt nhân là phần nằm ở trung tâm của nguyên tử.","e":"Hạt nhân nguyên tử gồm hai loại hạt là proton (mang điện tích dương) và neutron (không mang điện tích); electron chuyển động ở xung quanh hạt nhân.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Hạt proton trong hạt nhân nguyên tử mang điện tích:","o":["Điện tích âm","Không mang điện tích","Điện tích dương","Vừa mang điện tích dương vừa mang điện tích âm"],"a":"Điện tích dương","h":"Proton là hạt viết tắt là p, nằm trong hạt nhân.","e":"Proton mang điện tích dương (+1), electron mang điện tích âm (-1), còn neutron không mang điện tích.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Hạt electron trong nguyên tử mang điện tích:","o":["Điện tích dương","Không mang điện tích","Lúc dương lúc âm tuỳ theo vị trí","Điện tích âm"],"a":"Điện tích âm","h":"Electron là hạt rất nhẹ, chuyển động xung quanh hạt nhân.","e":"Electron mang điện tích âm (-1). Vì số proton bằng số electron nên nguyên tử trung hoà về điện.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Hạt neutron trong hạt nhân nguyên tử có đặc điểm là:","o":["Không mang điện tích","Mang điện tích dương","Mang điện tích âm","Mang điện tích dương gấp đôi proton"],"a":"Không mang điện tích","h":"Tên gọi neutron gợi ý về tính trung hoà điện.","e":"Neutron là hạt không mang điện tích, cùng với proton tạo nên hạt nhân nguyên tử.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Nguyên tố hoá học là:","o":["Tập hợp các nguyên tử có cùng số neutron trong hạt nhân","Tập hợp các nguyên tử có cùng số proton trong hạt nhân","Tập hợp các phân tử giống hệt nhau về khối lượng","Một chất bất kì được tạo thành từ hai nguyên tố trở lên"],"a":"Tập hợp các nguyên tử có cùng số proton trong hạt nhân","h":"Hãy chú ý đến đại lượng quyết định một nguyên tử thuộc nguyên tố nào.","e":"Nguyên tố hoá học là tập hợp các nguyên tử có cùng số proton trong hạt nhân; số proton là đặc trưng của một nguyên tố.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Kí hiệu hoá học của nguyên tố sắt là:","o":["Ir","S","Fe","F"],"a":"Fe","h":"Kí hiệu này bắt nguồn từ tên Latin của sắt là Ferrum.","e":"Sắt có kí hiệu hoá học là Fe (từ tiếng Latin Ferrum); S là lưu huỳnh, F là flo (fluorine).","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Kí hiệu hoá học Al dùng để chỉ nguyên tố nào?","o":["Bạc","Vàng","Sắt","Nhôm"],"a":"Nhôm","h":"Đây là kim loại nhẹ, thường dùng làm nồi, chảo và vỏ máy bay.","e":"Al là kí hiệu của nguyên tố nhôm (aluminium); bạc là Ag, vàng là Au, sắt là Fe.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Phân tử là:","o":["Hạt gồm một số nguyên tử liên kết với nhau, đại diện cho chất và mang đầy đủ tính chất hoá học của chất đó","Hạt nhỏ nhất cấu tạo nên hạt nhân nguyên tử","Một loại hạt mang điện tích dương trong nguyên tử","Tập hợp nhiều chất khác nhau trộn lẫn vào nhau"],"a":"Hạt gồm một số nguyên tử liên kết với nhau, đại diện cho chất và mang đầy đủ tính chất hoá học của chất đó","h":"Ví dụ: một phân tử nước gồm các nguyên tử hydrogen và oxygen liên kết với nhau.","e":"Phân tử là hạt đại diện cho chất, được tạo thành từ một số nguyên tử liên kết với nhau và mang đầy đủ tính chất hoá học của chất.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Chất nào sau đây là đơn chất?","o":["Nước (H2O)","Khí oxygen (O2)","Khí carbon dioxide (CO2)","Muối ăn (NaCl)"],"a":"Khí oxygen (O2)","h":"Hãy đếm số nguyên tố tạo thành mỗi chất.","e":"Đơn chất là chất tạo thành từ một nguyên tố hoá học; O2 chỉ do nguyên tố oxygen tạo nên, còn H2O, CO2, NaCl đều do từ hai nguyên tố trở lên tạo thành nên là hợp chất.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Chất nào sau đây là hợp chất?","o":["Kim loại đồng (Cu)","Khí nitrogen (N2)","Nước (H2O)","Khí hydrogen (H2)"],"a":"Nước (H2O)","h":"Hợp chất phải do từ hai nguyên tố hoá học trở lên tạo thành.","e":"Hợp chất là chất tạo thành từ hai nguyên tố hoá học trở lên; nước H2O do hydrogen và oxygen tạo thành, còn Cu, N2, H2 đều là đơn chất.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Hoá trị của một nguyên tố hoá học là:","o":["Khối lượng của một nguyên tử tính bằng đơn vị amu","Tổng số electron có trong một nguyên tử","Số thứ tự của nguyên tố trong bảng tuần hoàn","Con số biểu thị khả năng liên kết của nguyên tử nguyên tố đó với nguyên tử của nguyên tố khác"],"a":"Con số biểu thị khả năng liên kết của nguyên tử nguyên tố đó với nguyên tử của nguyên tố khác","h":"Hoá trị cho biết một nguyên tử có thể liên kết với bao nhiêu nguyên tử khác.","e":"Hoá trị là con số biểu thị khả năng liên kết của nguyên tử nguyên tố này với nguyên tử nguyên tố khác, thường được biểu diễn bằng chữ số La Mã.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Công thức hoá học H2O cho biết một phân tử nước được tạo thành từ:","o":["2 nguyên tử hydrogen và 1 nguyên tử oxygen","1 nguyên tử hydrogen và 2 nguyên tử oxygen","2 phân tử hydrogen và 1 phân tử oxygen","1 nguyên tử hydrogen và 1 nguyên tử oxygen"],"a":"2 nguyên tử hydrogen và 1 nguyên tử oxygen","h":"Chỉ số nhỏ ở dưới chân mỗi kí hiệu cho biết số nguyên tử của nguyên tố đó.","e":"Trong công thức H2O, chỉ số 2 ở dưới chân H cho biết có 2 nguyên tử hydrogen, còn O không có chỉ số nghĩa là có 1 nguyên tử oxygen.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Biết khối lượng nguyên tử của hydrogen là 1 amu và của oxygen là 16 amu. Khối lượng phân tử của nước (H2O) bằng:","o":["17 amu","18 amu","32 amu","34 amu"],"a":"18 amu","h":"Hãy cộng khối lượng của tất cả các nguyên tử có trong một phân tử nước.","e":"Phân tử H2O gồm 2 nguyên tử H và 1 nguyên tử O nên khối lượng phân tử bằng 2 × 1 + 16 = 18 amu.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Tốc độ của một chuyển động được tính bằng công thức nào?","o":["v = s × t","v = t/s","v = s/t","v = s − t"],"a":"v = s/t","h":"Tốc độ cho biết quãng đường đi được trong một đơn vị thời gian.","e":"Tốc độ bằng quãng đường đi được chia cho thời gian đi hết quãng đường đó: v = s/t.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Trong thực tế, tốc độ thường được đo bằng các đơn vị nào?","o":["Mét (m) và kilômét (km)","Giây (s) và giờ (h)","Kilôgam (kg) và tấn (t)","Mét trên giây (m/s) và kilômét trên giờ (km/h)"],"a":"Mét trên giây (m/s) và kilômét trên giờ (km/h)","h":"Đơn vị tốc độ phải gồm đơn vị quãng đường chia cho đơn vị thời gian.","e":"Đơn vị tốc độ thường dùng là m/s và km/h; m, km là đơn vị quãng đường còn s, h là đơn vị thời gian.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Một bạn học sinh chạy quãng đường 100 m trong thời gian 20 s. Tốc độ của bạn học sinh đó là:","o":["5 m/s","20 m/s","0,5 m/s","2000 m/s"],"a":"5 m/s","h":"Hãy áp dụng công thức v = s/t.","e":"Tốc độ của bạn học sinh là v = s/t = 100/20 = 5 m/s.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Âm thanh được phát ra khi nào?","o":["Khi một vật đứng yên hoàn toàn","Khi một vật dao động","Khi một vật bị nung nóng","Khi một vật bị chiếu sáng"],"a":"Khi một vật dao động","h":"Hãy nghĩ đến dây đàn khi được gảy.","e":"Mọi âm thanh đều do vật dao động phát ra; dao động càng mạnh, âm phát ra càng to.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Âm thanh có thể truyền qua được các môi trường nào?","o":["Chỉ chất khí","Chỉ chất rắn và chất lỏng","Chất rắn, chất lỏng và chất khí","Chất rắn, chất lỏng, chất khí và cả chân không"],"a":"Chất rắn, chất lỏng và chất khí","h":"Ta nghe được tiếng gõ cửa qua cánh cửa gỗ và nghe cá heo gọi nhau dưới nước.","e":"Âm thanh truyền qua được chất rắn, chất lỏng và chất khí, nhưng không truyền được qua chân không vì ở đó không có vật chất.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Hai nhà du hành vũ trụ làm việc ngoài không gian không thể trò chuyện trực tiếp với nhau mà phải dùng máy bộ đàm. Nguyên nhân là:","o":["Âm thanh truyền qua chân không quá chậm nên không nghe kịp","Tiếng nói bị trọng lực của Trái Đất kéo ngược trở lại","Âm thanh chỉ truyền được trong không khí giàu oxygen","Âm thanh không truyền được qua chân không vì không có môi trường vật chất để truyền dao động"],"a":"Âm thanh không truyền được qua chân không vì không có môi trường vật chất để truyền dao động","h":"Ngoài không gian vũ trụ gần như không có vật chất.","e":"Âm thanh cần môi trường vật chất (rắn, lỏng, khí) để truyền dao động; ngoài không gian là chân không nên tiếng nói không truyền đi được.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Độ to của âm thanh phụ thuộc vào yếu tố nào của dao động?","o":["Biên độ dao động","Tần số dao động","Tốc độ truyền âm","Khoảng cách từ nguồn âm đến tai"],"a":"Biên độ dao động","h":"Gảy dây đàn mạnh tay thì dây dao động thế nào và âm nghe ra sao?","e":"Biên độ dao động càng lớn thì âm phát ra càng to; biên độ dao động càng nhỏ thì âm phát ra càng nhỏ.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Độ cao của âm thanh phụ thuộc vào yếu tố nào?","o":["Biên độ dao động: biên độ càng lớn, âm càng cao","Tần số dao động: tần số càng lớn, âm phát ra càng cao","Kích thước của nguồn âm: nguồn âm càng to, âm càng cao","Môi trường truyền âm: truyền qua chất rắn âm cao hơn qua chất khí"],"a":"Tần số dao động: tần số càng lớn, âm phát ra càng cao","h":"Âm cao hay thấp gắn liền với số dao động trong một giây.","e":"Tần số dao động càng lớn thì âm phát ra càng cao (càng bổng); tần số càng nhỏ thì âm phát ra càng thấp (càng trầm).","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Trong một môi trường trong suốt và đồng tính, ánh sáng truyền đi theo:","o":["Đường cong","Đường gấp khúc","Đường thẳng","Đường tròn"],"a":"Đường thẳng","h":"Hãy quan sát tia nắng xuyên qua khe cửa hẹp.","e":"Ánh sáng truyền đi theo đường thẳng trong môi trường trong suốt và đồng tính; đây là định luật truyền thẳng của ánh sáng.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Ảnh của một vật tạo bởi gương phẳng có đặc điểm nào sau đây?","o":["Là ảnh thật, hứng được trên màn chắn và bằng vật","Là ảnh ảo, luôn nhỏ hơn vật","Là ảnh ảo, luôn lớn hơn vật","Là ảnh ảo, có kích thước bằng vật"],"a":"Là ảnh ảo, có kích thước bằng vật","h":"Hãy nhớ lại thí nghiệm dùng tấm kính trong và hai cây nến giống nhau.","e":"Ảnh tạo bởi gương phẳng là ảnh ảo (không hứng được trên màn), có kích thước bằng vật và đối xứng với vật qua mặt gương.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Một thanh nam châm có hai cực là cực Bắc (kí hiệu N) và cực Nam (kí hiệu S). Khi đưa cực Bắc của thanh nam châm này lại gần cực Bắc của một thanh nam châm khác, hiện tượng xảy ra là:","o":["Hai nam châm đẩy nhau","Hai nam châm hút nhau","Không xảy ra hiện tượng gì","Cả hai nam châm mất hết từ tính"],"a":"Hai nam châm đẩy nhau","h":"Hãy nhớ quy tắc: cùng cực thì..., khác cực thì...","e":"Hai cực cùng tên của nam châm thì đẩy nhau, hai cực khác tên thì hút nhau; ở đây cả hai đều là cực Bắc nên chúng đẩy nhau.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"La bàn giúp ta xác định được phương hướng là nhờ:","o":["Kim la bàn luôn chỉ về phía Mặt Trời mọc","Kim la bàn là một nam châm nhỏ, luôn tự định hướng theo hướng Bắc – Nam dưới tác dụng của từ trường Trái Đất","Trong la bàn có một động cơ nhỏ làm kim quay về hướng Bắc","Kim la bàn chỉ về nơi có nhiều ánh sáng nhất"],"a":"Kim la bàn là một nam châm nhỏ, luôn tự định hướng theo hướng Bắc – Nam dưới tác dụng của từ trường Trái Đất","h":"Hãy liên hệ tính chất của nam châm với việc kim la bàn tự quay khi để tự do.","e":"Kim la bàn là một nam châm nhỏ được đặt tự do nên dưới tác dụng của từ trường Trái Đất, nó luôn định hướng sao cho một đầu chỉ hướng Bắc, một đầu chỉ hướng Nam.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Trao đổi chất ở sinh vật là quá trình:","o":["Cơ thể sinh vật tăng lên về kích thước và khối lượng","Sinh vật tạo ra các cá thể mới giống mình","Cơ thể lấy các chất cần thiết từ môi trường vào và thải các chất cặn bã ra môi trường","Lá cây tổng hợp chất hữu cơ từ nước và khí carbon dioxide"],"a":"Cơ thể lấy các chất cần thiết từ môi trường vào và thải các chất cặn bã ra môi trường","h":"Hãy nghĩ đến việc cơ thể hằng ngày ăn, uống và thải chất thừa ra ngoài.","e":"Trao đổi chất là quá trình cơ thể sinh vật lấy các chất cần thiết từ môi trường (thức ăn, nước, oxygen...) và thải các chất cặn bã ra môi trường.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Quang hợp là quá trình diễn ra chủ yếu ở lá cây, trong đó:","o":["Cây phân giải chất hữu cơ để lấy năng lượng cho hoạt động sống","Cây hấp thụ khí oxygen và thải ra khí carbon dioxide","Cây hút muối khoáng từ đất để tạo ra hạt giống","Cây sử dụng nước, khí carbon dioxide và năng lượng ánh sáng để tổng hợp chất hữu cơ, đồng thời giải phóng khí oxygen"],"a":"Cây sử dụng nước, khí carbon dioxide và năng lượng ánh sáng để tổng hợp chất hữu cơ, đồng thời giải phóng khí oxygen","h":"Đây là quá trình giúp cây tự chế tạo thức ăn cho mình.","e":"Quang hợp là quá trình lá cây dùng nước, khí carbon dioxide và năng lượng ánh sáng mặt trời để tổng hợp chất hữu cơ và giải phóng khí oxygen.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Khí được cây xanh giải phóng ra môi trường trong quá trình quang hợp là:","o":["Khí oxygen (O2)","Khí carbon dioxide (CO2)","Khí nitrogen (N2)","Khí hydrogen (H2)"],"a":"Khí oxygen (O2)","h":"Đây là khí cần cho sự hô hấp của người và động vật.","e":"Trong quang hợp, cây hấp thụ khí carbon dioxide và giải phóng khí oxygen; nhờ đó cây xanh giúp bổ sung oxygen cho không khí.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Yếu tố nào sau đây không ảnh hưởng trực tiếp đến quá trình quang hợp của cây?","o":["Cường độ ánh sáng chiếu vào cây","Âm thanh từ môi trường xung quanh","Lượng nước cây được cung cấp","Nồng độ khí carbon dioxide trong không khí"],"a":"Âm thanh từ môi trường xung quanh","h":"Hãy liệt kê các nguyên liệu và điều kiện mà quang hợp cần.","e":"Quang hợp cần ánh sáng, nước và khí carbon dioxide nên các yếu tố này ảnh hưởng trực tiếp đến quang hợp; âm thanh không tham gia vào quá trình quang hợp.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Hô hấp tế bào là quá trình tế bào:","o":["Tổng hợp chất hữu cơ từ nước và khí carbon dioxide nhờ ánh sáng","Tạo ra khí oxygen và giải phóng ra ngoài cơ thể","Phân giải chất hữu cơ với sự tham gia của khí oxygen để giải phóng năng lượng cần cho các hoạt động sống","Vận chuyển khí oxygen từ phổi đi khắp cơ thể"],"a":"Phân giải chất hữu cơ với sự tham gia của khí oxygen để giải phóng năng lượng cần cho các hoạt động sống","h":"Đây là quá trình cung cấp năng lượng cho mọi hoạt động của tế bào.","e":"Hô hấp tế bào phân giải chất hữu cơ (với sự tham gia của oxygen) thành carbon dioxide và nước, đồng thời giải phóng năng lượng cho các hoạt động sống.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Một chậu cây đặt gần cửa sổ, sau vài ngày ngọn cây cong và mọc hướng về phía có ánh sáng. Hiện tượng này thể hiện khả năng nào của cây?","o":["Di chuyển từ nơi tối sang nơi sáng","Sinh sản để tạo ra cây con","Thải các chất cặn bã ra ngoài","Cảm ứng — phản ứng lại kích thích ánh sáng từ môi trường"],"a":"Cảm ứng — phản ứng lại kích thích ánh sáng từ môi trường","h":"Sinh vật có một tính chất là phản ứng lại các tác động của môi trường.","e":"Cây mọc hướng về phía ánh sáng là phản ứng cảm ứng của cây đối với kích thích ánh sáng; cảm ứng là khả năng sinh vật phản ứng lại các kích thích từ môi trường.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Khi chạm nhẹ vào lá cây xấu hổ (cây trinh nữ), các lá chét lập tức khép lại. Đây là biểu hiện của tính chất nào của sinh vật?","o":["Cảm ứng với kích thích","Sinh trưởng","Sinh sản","Trao đổi chất"],"a":"Cảm ứng với kích thích","h":"Lá khép lại ngay sau khi bị chạm vào là một phản ứng.","e":"Lá cây xấu hổ khép lại khi bị chạm là phản ứng của cây trước kích thích tiếp xúc, tức là biểu hiện của tính cảm ứng ở thực vật.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Sinh trưởng ở sinh vật là:","o":["Sự biến đổi về cấu tạo và chức năng của các cơ quan","Sự tăng lên về kích thước và khối lượng của cơ thể","Sự hình thành các cá thể mới từ cơ thể bố mẹ","Sự phản ứng với các kích thích từ môi trường"],"a":"Sự tăng lên về kích thước và khối lượng của cơ thể","h":"Hãy nghĩ đến một cây con lớn dần thành cây trưởng thành.","e":"Sinh trưởng là quá trình cơ thể sinh vật tăng lên về kích thước và khối lượng nhờ sự tăng số lượng và kích thước tế bào.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Phát triển ở sinh vật là quá trình:","o":["Chỉ tăng lên về kích thước và khối lượng của cơ thể","Tạo ra các cá thể mới giống cơ thể bố mẹ","Biến đổi về cấu tạo và chức năng của tế bào, mô, cơ quan và cơ thể, diễn ra cùng với sinh trưởng","Lấy các chất dinh dưỡng từ môi trường vào cơ thể"],"a":"Biến đổi về cấu tạo và chức năng của tế bào, mô, cơ quan và cơ thể, diễn ra cùng với sinh trưởng","h":"Ví dụ: mầm cây không chỉ to lên mà còn ra lá, ra hoa.","e":"Phát triển là quá trình biến đổi về cấu tạo và chức năng của tế bào, mô, cơ quan và cơ thể; nó diễn ra đồng thời và gắn liền với sinh trưởng.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Nông dân trồng cây sắn (khoai mì) và cây mía bằng cách cắm một đoạn thân xuống đất để đoạn thân mọc thành cây mới. Hình thức sinh sản này thuộc loại:","o":["Sinh sản hữu tính","Sinh sản nhờ thụ phấn và thụ tinh","Sinh sản chỉ có ở động vật","Sinh sản vô tính"],"a":"Sinh sản vô tính","h":"Cây mới mọc lên từ một phần của cây mẹ, không qua hoa và hạt.","e":"Cây mới được tạo thành từ một phần của cơ thể mẹ (đoạn thân) mà không có sự kết hợp của giao tử nên đây là sinh sản vô tính (sinh sản sinh dưỡng).","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Vi khuẩn sinh sản chủ yếu bằng cách phân đôi: một tế bào mẹ tách thành hai tế bào con giống hệt nhau và không có sự kết hợp của giao tử. Đây là hình thức:","o":["Sinh sản vô tính","Sinh sản hữu tính","Thụ tinh ngoài","Sinh sản bằng hoa"],"a":"Sinh sản vô tính","h":"Hãy căn cứ vào đặc điểm: có hay không có sự kết hợp của giao tử.","e":"Vì quá trình phân đôi không có sự kết hợp giữa giao tử đực và giao tử cái nên sinh sản của vi khuẩn là sinh sản vô tính.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Đặc điểm cơ bản của sinh sản hữu tính là:","o":["Cơ thể mới được tạo thành từ một đoạn thân hoặc lá của cơ thể mẹ","Có sự kết hợp giữa giao tử đực và giao tử cái tạo thành hợp tử, từ đó phát triển thành cơ thể mới","Chỉ cần một cá thể duy nhất cũng tạo được cơ thể mới giống hệt mình","Cơ thể mới nảy mầm trực tiếp từ hạt phấn bay trong gió"],"a":"Có sự kết hợp giữa giao tử đực và giao tử cái tạo thành hợp tử, từ đó phát triển thành cơ thể mới","h":"Từ khoá cần chú ý là giao tử và hợp tử.","e":"Sinh sản hữu tính có sự kết hợp giữa giao tử đực và giao tử cái tạo thành hợp tử; hợp tử phát triển thành cơ thể mới mang đặc điểm của cả bố và mẹ.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Nước có vai trò quan trọng nào đối với cây trồng?","o":["Cung cấp năng lượng trực tiếp cho cây hoạt động","Thay thế hoàn toàn được muối khoáng trong đất","Vừa là nguyên liệu cho quang hợp, vừa giúp hoà tan và vận chuyển các chất trong cây","Giúp cây tự tạo ra ánh sáng để quang hợp"],"a":"Vừa là nguyên liệu cho quang hợp, vừa giúp hoà tan và vận chuyển các chất trong cây","h":"Cây bị héo khi thiếu nước vì nhiều hoạt động sống bị ảnh hưởng.","e":"Nước là nguyên liệu của quang hợp, là dung môi hoà tan muối khoáng và giúp vận chuyển các chất trong cây, đồng thời giữ cho cây luôn tươi tốt.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Vì sao cây trồng cần được cung cấp muối khoáng (qua đất và phân bón)?","o":["Muối khoáng là nguồn năng lượng chính mà cây hấp thụ để sống","Muối khoáng giúp lá cây tự phát ra ánh sáng vào ban đêm","Cây không hấp thụ muối khoáng, bón phân chỉ để làm đất tơi xốp","Muối khoáng chứa các nguyên tố dinh dưỡng cần thiết như đạm, lân, kali giúp cây sinh trưởng và phát triển tốt"],"a":"Muối khoáng chứa các nguyên tố dinh dưỡng cần thiết như đạm, lân, kali giúp cây sinh trưởng và phát triển tốt","h":"Đất trồng lâu ngày bị bạc màu nên người nông dân phải bón phân.","e":"Muối khoáng (đạm, lân, kali...) là nguồn nguyên tố dinh dưỡng thiết yếu; cây hấp thụ muối khoáng hoà tan trong nước để sinh trưởng và phát triển.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Khi chiếu một tia sáng tới bề mặt gương phẳng, theo định luật phản xạ ánh sáng, góc phản xạ (góc tạo bởi tia phản xạ và pháp tuyến) có quan hệ thế nào với góc tới?","o":["Góc phản xạ luôn lớn hơn góc tới","Góc phản xạ bằng góc tới","Góc phản xạ luôn nhỏ hơn góc tới","Góc phản xạ không liên quan gì đến góc tới"],"a":"Góc phản xạ bằng góc tới","h":"Hai góc này được đo so với đường pháp tuyến vuông góc với gương.","e":"Định luật phản xạ ánh sáng: tia phản xạ nằm trong cùng mặt phẳng với tia tới và pháp tuyến, và góc phản xạ luôn bằng góc tới.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Khi nào phía sau một vật xuất hiện vùng bóng tối (vùng tối) hoàn toàn không nhận được ánh sáng?","o":["Khi vật làm bằng nhựa trong suốt","Khi trời chuyển sang ban đêm","Khi có gương đặt phía sau vật","Khi nguồn sáng bị vật cản không trong suốt chắn lại, ánh sáng không chiếu tới được vùng đó"],"a":"Khi nguồn sáng bị vật cản không trong suốt chắn lại, ánh sáng không chiếu tới được vùng đó","h":"Ánh sáng truyền theo đường thẳng nên không \"bẻ cong\" qua vật cản được.","e":"Vì ánh sáng truyền thẳng, vùng phía sau vật cản không trong suốt không nhận được ánh sáng từ nguồn sáng, tạo thành bóng tối. Nhật thực là một ví dụ: Mặt Trăng chắn ánh sáng Mặt Trời, tạo vùng bóng tối trên Trái Đất.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Khi đứng trước một vách núi và hét to, em nghe lại tiếng của chính mình sau một lúc. Tiếng vang là gì?","o":["Âm thanh do vách núi tự phát ra","Âm thanh nghe được khi đứng trong phòng kín","Âm phản xạ nghe được tách biệt, sau âm trực tiếp một khoảng thời gian","Âm thanh truyền đi trong nước"],"a":"Âm phản xạ nghe được tách biệt, sau âm trực tiếp một khoảng thời gian","h":"Âm dội lại từ vật cản ở xa mới nghe tách riêng thành tiếng vang.","e":"Tiếng vang là âm phản xạ từ một bề mặt ở đủ xa (như vách núi, bức tường lớn) trở lại tai ta chậm hơn âm trực tiếp nên nghe tách biệt. Người ta ứng dụng sự phản xạ của sóng siêu âm để đo độ sâu đáy biển.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Khu nhà em ở gần một công trường xây dựng rất ồn. Biện pháp nào sau đây giúp chống ô nhiễm tiếng ồn hiệu quả?","o":["Mở nhạc thật to để át đi tiếng ồn","Trồng cây xanh quanh nhà, dùng cửa kính cách âm và đề nghị công trường hạn chế làm việc gây ồn vào giờ nghỉ","La hét thật to cho quen dần với tiếng ồn","Bịt tai bằng tay mỗi khi có tiếng ồn"],"a":"Trồng cây xanh quanh nhà, dùng cửa kính cách âm và đề nghị công trường hạn chế làm việc gây ồn vào giờ nghỉ","h":"Chống ồn gồm: giảm nguồn ồn, chặn đường truyền âm và bảo vệ tai.","e":"Để chống ô nhiễm tiếng ồn, ta kết hợp: hạn chế nguồn gây ồn, ngăn âm truyền qua (cây xanh, tường, cửa cách âm) và bảo vệ người nghe. Mở nhạc to hơn chỉ làm tổng tiếng ồn càng lớn.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Trên đồ thị quãng đường – thời gian của một chiếc xe, có một đoạn đồ thị là đường thẳng nằm ngang, song song với trục thời gian. Đoạn đó cho biết xe đang:","o":["Chuyển động ngày càng nhanh","Chuyển động ngày càng chậm","Quay ngược trở lại điểm xuất phát","Đứng yên, không chuyển động"],"a":"Đứng yên, không chuyển động","h":"Thời gian vẫn trôi nhưng quãng đường đi được có tăng không?","e":"Đồ thị nằm ngang nghĩa là thời gian tăng lên nhưng quãng đường không đổi, tức là vật đứng yên. Đoạn đồ thị càng dốc thì vật chuyển động càng nhanh.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Từ trường tồn tại xung quanh nam châm nhưng mắt thường không nhìn thấy được. Để phát hiện ở một vị trí có từ trường hay không, người ta thường dùng gì?","o":["Một kim nam châm nhỏ đặt tự do","Một chiếc thước kẻ nhựa","Một nhiệt kế thuỷ ngân","Một viên pin tiểu"],"a":"Một kim nam châm nhỏ đặt tự do","h":"Dụng cụ này luôn bị từ trường làm lệch khỏi hướng Bắc – Nam.","e":"Kim nam châm nhỏ đặt trong từ trường sẽ bị lực từ tác dụng và quay lệch đi. Quan sát sự lệch của kim nam châm giúp ta nhận biết và khảo sát từ trường quanh nam châm.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Một nam châm điện hút đinh sắt yếu hơn mong muốn. Muốn nam châm điện hút mạnh hơn, ta có thể làm cách nào?","o":["Giảm cường độ dòng điện chạy qua cuộn dây","Tháo bớt một số vòng dây của cuộn dây","Tăng cường độ dòng điện hoặc tăng số vòng dây của cuộn dây","Ngắt hẳn dòng điện khỏi cuộn dây"],"a":"Tăng cường độ dòng điện hoặc tăng số vòng dây của cuộn dây","h":"Từ trường của nam châm điện mạnh lên khi dòng điện hoặc số vòng dây thay đổi thế nào?","e":"Nam châm điện hút mạnh hơn khi cường độ dòng điện qua cuộn dây lớn hơn hoặc số vòng dây nhiều hơn. Ngược lại, giảm dòng điện hay bớt vòng dây sẽ làm lực hút yếu đi.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Liên kết hoá học là gì?","o":["Sự liên kết giữa các nguyên tử để tạo thành phân tử hoặc hợp chất bền vững hơn","Sự trộn lẫn hai chất với nhau bằng thìa","Lực hút giữa Trái Đất và một vật","Sự buộc hai đồ vật lại bằng sợi dây"],"a":"Sự liên kết giữa các nguyên tử để tạo thành phân tử hoặc hợp chất bền vững hơn","h":"Nhờ có liên kết này mà các nguyên tử \"gắn\" với nhau thành phân tử nước, muối ăn...","e":"Liên kết hoá học là sự liên kết giữa các nguyên tử với nhau. Nhờ liên kết hoá học, các nguyên tử tạo thành phân tử và hợp chất bền vững hơn so với khi chúng đứng riêng lẻ.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Ở cây xanh, quá trình trao đổi khí với môi trường (lấy khí carbon dioxide vào và thải khí oxygen ra khi quang hợp) diễn ra chủ yếu qua bộ phận nào?","o":["Qua các lỗ khí khổng trên lá","Qua vỏ cứng của thân cây","Qua đầu các sợi rễ dưới đất","Qua cánh hoa"],"a":"Qua các lỗ khí khổng trên lá","h":"Trên lá có những lỗ rất nhỏ có thể đóng mở được.","e":"Khí khổng là những lỗ nhỏ trên bề mặt lá, có thể đóng mở. Qua khí khổng, cây lấy khí carbon dioxide cho quang hợp, thải khí oxygen ra và cũng thoát hơi nước.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Ở động vật, việc lấy thức ăn vào cơ thể và vận chuyển chất dinh dưỡng đi nuôi các bộ phận do những hệ cơ quan nào đảm nhiệm?","o":["Hệ hô hấp lấy thức ăn, hệ bài tiết vận chuyển","Hệ tiêu hoá lấy và tiêu hoá thức ăn, hệ tuần hoàn vận chuyển chất dinh dưỡng","Hệ thần kinh lấy thức ăn, hệ xương vận chuyển","Hệ tuần hoàn lấy thức ăn, hệ tiêu hoá vận chuyển máu"],"a":"Hệ tiêu hoá lấy và tiêu hoá thức ăn, hệ tuần hoàn vận chuyển chất dinh dưỡng","h":"Thức ăn được nghiền nhỏ và biến đổi trong ống tiêu hoá trước khi vào máu.","e":"Hệ tiêu hoá lấy thức ăn vào và tiêu hoá thành chất dinh dưỡng đơn giản. Các chất này được hấp thụ vào máu và hệ tuần hoàn vận chuyển chúng đến mọi bộ phận của cơ thể, đồng thời mang chất thải đi.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Khi học môn Khoa học tự nhiên, để tìm hiểu một hiện tượng, trình tự công việc hợp lí nhất là:","o":["Quan sát, đặt câu hỏi, đưa ra dự đoán, làm thí nghiệm kiểm chứng rồi rút ra kết luận","Đọc thuộc lòng kết luận trong sách trước rồi mới quan sát","Chỉ cần hỏi ý kiến bạn bè, không cần làm thí nghiệm","Làm thí nghiệm trước, quan sát sau cùng"],"a":"Quan sát, đặt câu hỏi, đưa ra dự đoán, làm thí nghiệm kiểm chứng rồi rút ra kết luận","h":"Đây chính là tiến trình tìm tòi, khám phá tự nhiên của các nhà khoa học.","e":"Phương pháp học tập và nghiên cứu khoa học tự nhiên gồm các bước: quan sát hiện tượng, đặt câu hỏi, hình thành giả thuyết (dự đoán), lập kế hoạch và làm thí nghiệm kiểm chứng, phân tích kết quả và rút ra kết luận.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Nhận định nào sau đây đúng về bảng tuần hoàn các nguyên tố hoá học (ở mức sơ lược)?","o":["Các nguyên tố được xếp ngẫu nhiên theo thứ tự chữ cái","Mỗi ô trong bảng cho biết thông tin về một nguyên tố; các nguyên tố được sắp xếp theo chiều tăng dần của số hiệu nguyên tử","Bảng tuần hoàn chỉ gồm đúng 10 nguyên tố","Các nguyên tố trong cùng một hàng đều là kim loại"],"a":"Mỗi ô trong bảng cho biết thông tin về một nguyên tố; các nguyên tố được sắp xếp theo chiều tăng dần của số hiệu nguyên tử","h":"Số hiệu nguyên tử bằng số proton trong hạt nhân của nguyên tố.","e":"Bảng tuần hoàn sắp xếp các nguyên tố hoá học theo chiều tăng dần của số hiệu nguyên tử (bằng số proton). Mỗi ô nguyên tố cho biết số hiệu, kí hiệu hoá học, tên nguyên tố và khối lượng nguyên tử của nguyên tố đó.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Vì sao khi tham gia giao thông, chạy xe với tốc độ càng cao thì càng nguy hiểm?","o":["Vì tốc độ cao làm xăng tốn ít hơn","Vì khi chạy nhanh, quãng đường phanh dài hơn và khó xử lí tình huống bất ngờ, dễ gây tai nạn nghiêm trọng","Vì tốc độ cao làm đường nhựa nhanh hỏng","Vì chạy nhanh thì xe rung nhiều gây mệt"],"a":"Vì khi chạy nhanh, quãng đường phanh dài hơn và khó xử lí tình huống bất ngờ, dễ gây tai nạn nghiêm trọng","h":"Hãy liên hệ bài Tốc độ với bài học về an toàn giao thông.","e":"Tốc độ càng lớn, xe cần quãng đường càng dài mới dừng hẳn được sau khi phanh, đồng thời thời gian để người lái phản ứng xử lí tình huống bị rút ngắn. Vì vậy, chạy quá tốc độ quy định là nguyên nhân hàng đầu gây tai nạn giao thông nghiêm trọng.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Sau khi thu hoạch, nông dân thường phơi khô hạt thóc, hạt ngô và bảo quản nơi khô ráo, thoáng mát. Cách bảo quản này có tác dụng gì?","o":["Làm hạt hô hấp mạnh hơn để nảy mầm nhanh","Làm giảm hô hấp tế bào của hạt, tránh hao hụt chất dinh dưỡng và tránh nấm mốc","Làm hạt tăng thêm khối lượng","Làm hạt quang hợp để tạo thêm chất dinh dưỡng"],"a":"Làm giảm hô hấp tế bào của hạt, tránh hao hụt chất dinh dưỡng và tránh nấm mốc","h":"Hô hấp tế bào tiêu hao chất hữu cơ trong hạt; yếu tố nào làm hô hấp chậm lại?","e":"Hạt khô và môi trường khô ráo, nhiệt độ thấp làm quá trình hô hấp tế bào của hạt giảm xuống mức thấp nhất, nên chất dinh dưỡng trong hạt ít bị tiêu hao, hạt bảo quản được lâu và tránh được nấm mốc gây hỏng.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Ở cây xanh, nước được rễ hút từ đất rồi được vận chuyển lên lá chủ yếu qua bộ phận nào của thân, và lá thoát hơi nước ra ngoài qua đâu?","o":["Qua ruột của thân, thoát ra qua hoa","Qua mạch gỗ của thân, thoát ra qua các khí khổng trên lá","Qua vỏ thân, thoát ra qua quả","Qua lông hút của lá, thoát ra qua rễ"],"a":"Qua mạch gỗ của thân, thoát ra qua các khí khổng trên lá","h":"Hãy nhớ dòng vận chuyển nước trong cây đi từ rễ lên lá.","e":"Rễ hút nước và muối khoáng từ đất, nước được mạch gỗ trong thân vận chuyển lên lá. Phần lớn nước thoát ra ngoài qua các khí khổng trên lá (thoát hơi nước), tạo động lực kéo dòng nước đi lên và giúp cây điều hoà nhiệt độ.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Nông dân làm giàn cho cây mướp, cây bí leo lên. Việc làm này đã vận dụng hiểu biết về tính chất nào của cây?","o":["Tính quang hợp của lá","Cảm ứng của cây: thân và tua cuốn của cây leo quấn vào giàn khi tiếp xúc (cảm ứng tiếp xúc)","Sinh sản vô tính của cây","Hô hấp tế bào của rễ"],"a":"Cảm ứng của cây: thân và tua cuốn của cây leo quấn vào giàn khi tiếp xúc (cảm ứng tiếp xúc)","h":"Tua cuốn phản ứng lại kích thích tiếp xúc với vật đỡ.","e":"Cây leo có tua cuốn cảm ứng với tiếp xúc: khi chạm vào giàn, tua cuốn quấn chặt lấy giàn giúp thân leo lên cao đón ánh sáng. Nông dân vận dụng tính cảm ứng này để làm giàn, giúp cây sinh trưởng tốt và cho nhiều quả.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Vào ban đêm, nhiều nhà vườn thắp đèn chiếu sáng cho cây thanh long để cây ra hoa, kết quả vào mùa trái vụ. Việc làm này dựa trên yếu tố nào ảnh hưởng đến sinh trưởng và phát triển của cây?","o":["Ánh sáng (thời gian chiếu sáng) điều khiển quá trình ra hoa của cây","Đèn làm đất ấm lên nên rễ mọc nhanh","Ánh sáng đèn xua đuổi hết côn trùng gây hại","Đèn giúp cây quang hợp thay cho Mặt Trời hoàn toàn"],"a":"Ánh sáng (thời gian chiếu sáng) điều khiển quá trình ra hoa của cây","h":"Thanh long ra hoa khi ngày dài; thắp đèn kéo dài thời gian chiếu sáng.","e":"Quá trình sinh trưởng và phát triển của cây chịu ảnh hưởng của ánh sáng, trong đó thời gian chiếu sáng trong ngày điều khiển sự ra hoa của nhiều loài cây. Thắp đèn ban đêm kéo dài thời gian chiếu sáng, kích thích thanh long ra hoa trái vụ, cho thu nhập cao hơn.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Để tăng tỉ lệ đậu quả cho cây ăn quả, người trồng cây thường thả ong trong vườn hoặc thụ phấn bổ sung bằng tay cho hoa. Việc làm này giúp ích gì?","o":["Giúp cây quang hợp nhanh hơn","Giúp hạt phấn đến được đầu nhuỵ của hoa nhiều hơn, tăng khả năng thụ tinh tạo quả","Giúp rễ cây hút được nhiều nước hơn","Giúp lá cây to và xanh hơn"],"a":"Giúp hạt phấn đến được đầu nhuỵ của hoa nhiều hơn, tăng khả năng thụ tinh tạo quả","h":"Quả và hạt được tạo thành sau quá trình thụ phấn, thụ tinh ở hoa.","e":"Sinh sản hữu tính ở thực vật cần thụ phấn (hạt phấn đến đầu nhuỵ) rồi thụ tinh mới tạo thành quả và hạt. Thả ong hoặc thụ phấn bổ sung bằng tay làm tăng lượng hạt phấn tới nhuỵ, nâng cao tỉ lệ đậu quả.","t":"khtn-lop7","g":7,"l":"nhe-nhang"},{"p":"Khi em chạy nhanh, tim đập nhanh hơn, nhịp thở tăng, người nóng lên và ra mồ hôi. Hiện tượng này chứng tỏ điều gì về cơ thể?","o":["Mỗi hệ cơ quan hoạt động hoàn toàn độc lập, không liên quan nhau","Cơ thể là một thể thống nhất: các hệ cơ quan (vận động, tuần hoàn, hô hấp, bài tiết...) phối hợp nhịp nhàng với nhau","Chỉ có hệ vận động tham gia khi cơ thể chạy","Tim và phổi ngừng phối hợp khi cơ thể mệt"],"a":"Cơ thể là một thể thống nhất: các hệ cơ quan (vận động, tuần hoàn, hô hấp, bài tiết...) phối hợp nhịp nhàng với nhau","h":"Khi vận động, cơ cần nhiều oxygen và năng lượng hơn, nên những hệ nào phải tăng hoạt động theo?","e":"Cơ thể sinh vật là một thể thống nhất: khi cơ bắp vận động mạnh, hệ tuần hoàn tăng nhịp tim để đưa máu, hệ hô hấp tăng nhịp thở để lấy thêm oxygen, da tiết mồ hôi để thải nhiệt. Các hệ cơ quan luôn phối hợp và ảnh hưởng lẫn nhau trong mọi hoạt động sống.","t":"khtn-lop7","g":7,"l":"thu-thach"},{"p":"Hiện tượng nào sau đây là biến đổi hoá học?","o":["Dây sắt để lâu ngoài trời bị gỉ, tạo thành lớp gỉ màu nâu đỏ","Nước đá tan chảy thành nước lỏng","Cồn trong lọ mở nắp bị bay hơi dần","Hoà tan đường vào nước được nước đường"],"a":"Dây sắt để lâu ngoài trời bị gỉ, tạo thành lớp gỉ màu nâu đỏ","h":"Hãy tìm hiện tượng có tạo thành chất mới.","e":"Sắt bị gỉ là do sắt tác dụng với oxygen và hơi nước tạo thành chất mới (gỉ sắt) nên là biến đổi hoá học; các hiện tượng còn lại chỉ thay đổi trạng thái hoặc hoà tan, không tạo chất mới.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Cho một mẩu kẽm vào ống nghiệm đựng dung dịch acid, thấy có nhiều bọt khí thoát ra. Hiện tượng sủi bọt khí chứng tỏ điều gì?","o":["Kẽm đang tan chảy vì acid quá nóng","Đã xảy ra phản ứng hoá học và có chất khí mới được tạo thành","Acid trong ống nghiệm đang sôi","Kẽm chỉ bị hoà tan vật lí, không có chất mới sinh ra"],"a":"Đã xảy ra phản ứng hoá học và có chất khí mới được tạo thành","h":"Bọt khí xuất phát từ một chất không hề có sẵn trong ống nghiệm ban đầu.","e":"Khí thoát ra là chất mới sinh ra trong phản ứng giữa kẽm và acid, nên sủi bọt khí là một dấu hiệu của phản ứng hoá học.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trộn hai dung dịch trong suốt lại với nhau, sau một lúc thấy xuất hiện chất rắn không tan lắng xuống đáy ống nghiệm. Dấu hiệu này cho biết:","o":["Hai dung dịch chưa được khuấy đều với nhau","Dung dịch đã bị nhiễm bẩn từ trước","Đã xảy ra phản ứng hoá học tạo thành chất mới không tan (kết tủa)","Chất rắn tan trong dung dịch bị đông lại vì lạnh"],"a":"Đã xảy ra phản ứng hoá học tạo thành chất mới không tan (kết tủa)","h":"Chất rắn đó không hề có trong hai dung dịch ban đầu.","e":"Chất kết tủa là chất mới được tạo thành sau khi trộn hai dung dịch, chứng tỏ đã xảy ra phản ứng hoá học.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Dấu hiệu nào sau đây KHÔNG phải là dấu hiệu cho thấy có phản ứng hoá học xảy ra?","o":["Xuất hiện chất rắn kết tủa","Có khí thoát ra, dung dịch sủi bọt","Dung dịch thay đổi màu sắc và toả nhiệt","Miếng bơ tan chảy khi để ở nhiệt độ phòng"],"a":"Miếng bơ tan chảy khi để ở nhiệt độ phòng","h":"Hãy xét xem hiện tượng nào không tạo ra chất mới.","e":"Bơ tan chảy chỉ là sự thay đổi trạng thái (biến đổi vật lí), không tạo chất mới; các dấu hiệu còn lại đều thường gắn với phản ứng hoá học.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Theo định luật bảo toàn khối lượng, trong một phản ứng hoá học:","o":["Tổng khối lượng của các chất tham gia bằng tổng khối lượng của các chất sản phẩm","Tổng khối lượng các chất sản phẩm luôn lớn hơn các chất tham gia","Khối lượng của từng chất riêng lẻ đều không thay đổi","Tổng số nguyên tử của các chất sản phẩm luôn nhỏ hơn các chất tham gia"],"a":"Tổng khối lượng của các chất tham gia bằng tổng khối lượng của các chất sản phẩm","h":"Trong phản ứng hoá học, các nguyên tử chỉ sắp xếp lại chứ không mất đi.","e":"Định luật bảo toàn khối lượng: tổng khối lượng các chất tham gia phản ứng bằng tổng khối lượng các chất sản phẩm.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Đốt cháy hoàn toàn 12 g carbon trong một bình kín chứa 32 g khí oxygen, phản ứng tạo thành khí carbon dioxide. Khối lượng khí carbon dioxide thu được là:","o":["20 g","44 g","32 g","384 g"],"a":"44 g","h":"Áp dụng định luật bảo toàn khối lượng cho phản ứng xảy ra trong bình kín.","e":"Theo định luật bảo toàn khối lượng: m(CO2) = m(C) + m(O2) = 12 + 32 = 44 g.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Cho phương trình hoá học: 2H2 + O2 → 2H2O. Tỉ lệ số phân tử của H2 : O2 : H2O trong phản ứng là:","o":["1 : 1 : 1","2 : 2 : 1","2 : 1 : 2","1 : 2 : 2"],"a":"2 : 1 : 2","h":"Đọc các hệ số đứng trước công thức của từng chất trong phương trình.","e":"Các hệ số trong phương trình lần lượt là 2, 1 (hệ số 1 thường không viết) và 2, nên tỉ lệ số phân tử H2 : O2 : H2O = 2 : 1 : 2.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Phương trình hoá học nào sau đây được cân bằng đúng?","o":["Mg + O2 → MgO","Mg + O2 → 2MgO","2Mg + 2O2 → 2MgO","2Mg + O2 → 2MgO"],"a":"2Mg + O2 → 2MgO","h":"Đếm số nguyên tử của mỗi nguyên tố ở hai vế của từng phương trình.","e":"Ở phương trình 2Mg + O2 → 2MgO, mỗi vế đều có 2 nguyên tử Mg và 2 nguyên tử O nên phương trình đã cân bằng; các phương trình còn lại đều lệch số nguyên tử ở hai vế.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Một mol của bất kì chất nào (nguyên tử, phân tử hay ion) đều chứa số hạt là:","o":["6,022 × 10^23 hạt","6,022 × 10^22 hạt","6,022 × 10^24 hạt","1,0 × 10^23 hạt"],"a":"6,022 × 10^23 hạt","h":"Con số này mang tên nhà khoa học Avogadro.","e":"Theo định nghĩa, 1 mol chất chứa 6,022 × 10^23 hạt vi mô; con số này gọi là số Avogadro.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khối lượng mol của nước (H2O) là bao nhiêu? Biết khối lượng nguyên tử của H là 1 amu và của O là 16 amu.","o":["17 g/mol","18 g/mol","20 g/mol","34 g/mol"],"a":"18 g/mol","h":"Phân tử nước gồm 2 nguyên tử H và 1 nguyên tử O.","e":"M(H2O) = 2 × 1 + 16 = 18 g/mol.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Số mol của 36 g nước (H2O, có khối lượng mol M = 18 g/mol) là:","o":["0,5 mol","1 mol","2 mol","3 mol"],"a":"2 mol","h":"Dùng công thức tính số mol: n = m/M.","e":"n = m/M = 36/18 = 2 mol.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Khi hoà tan muối ăn vào nước, ta được dung dịch nước muối. Trong dung dịch này:","o":["Muối ăn là dung môi, nước là chất tan","Muối ăn và nước đều là chất tan","Nước là chất tan, muối ăn là dung môi","Muối ăn là chất tan, nước là dung môi"],"a":"Muối ăn là chất tan, nước là dung môi","h":"Chất bị hoà tan vào chất kia được gọi là chất tan.","e":"Chất tan là chất bị hoà tan (muối ăn), dung môi là chất dùng để hoà tan chất khác (nước); hỗn hợp đồng nhất thu được gọi là dung dịch.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Hoà tan hoàn toàn 20 g muối ăn vào 180 g nước, thu được dung dịch muối có nồng độ phần trăm là:","o":["10%","20%","11,1%","9%"],"a":"10%","h":"Khối lượng dung dịch bằng khối lượng chất tan cộng với khối lượng dung môi.","e":"Khối lượng dung dịch = 20 + 180 = 200 g; C% = (20/200) × 100% = 10%.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Nhỏ dung dịch nước vôi trong (một base) lên giấy quỳ tím, quỳ tím sẽ:","o":["Chuyển sang màu đỏ","Chuyển sang màu xanh","Không đổi màu","Bị mất màu hoàn toàn"],"a":"Chuyển sang màu xanh","h":"Acid và base làm quỳ tím đổi màu ngược nhau.","e":"Dung dịch base làm quỳ tím hoá xanh; ngược lại, dung dịch acid làm quỳ tím hoá đỏ.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Giấm ăn có pH khoảng 3. Điều này cho biết giấm ăn:","o":["Có tính base","Là dung dịch trung tính","Có tính acid","Không phải là dung dịch"],"a":"Có tính acid","h":"So sánh giá trị pH của giấm ăn với mốc pH = 7.","e":"Thang pH chạy từ 0 đến 14: pH < 7 thì dung dịch có tính acid, pH = 7 trung tính, pH > 7 có tính base. Giấm ăn có pH = 3 < 7 nên có tính acid.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Chất nào sau đây thuộc loại muối?","o":["CO2","HCl","NaOH","NaCl"],"a":"NaCl","h":"Muối thường gồm nguyên tử kim loại liên kết với gốc acid.","e":"NaCl (natri clorua) là muối; CO2 là oxide, HCl là acid và NaOH là base.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khối lượng riêng của một chất được đo bằng đơn vị nào sau đây?","o":["kg/m³ hoặc g/cm³","kg","m³","N/m²"],"a":"kg/m³ hoặc g/cm³","h":"Khối lượng riêng là khối lượng của một đơn vị thể tích chất đó.","e":"Khối lượng riêng D = m/V nên đơn vị của nó là đơn vị khối lượng chia cho đơn vị thể tích, ví dụ kg/m³ hay g/cm³.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Một khối kim loại có khối lượng 540 g và thể tích 200 cm³. Khối lượng riêng của kim loại đó là:","o":["0,37 g/cm³","2,7 g/cm³","27 g/cm³","108 000 g/cm³"],"a":"2,7 g/cm³","h":"Dùng công thức khối lượng riêng: D = m/V.","e":"D = m/V = 540/200 = 2,7 g/cm³.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Để tăng áp suất do một vật rắn tác dụng lên mặt bị ép, người ta cần:","o":["Tăng diện tích bị ép và giảm áp lực","Giảm áp lực tác dụng lên mặt bị ép","Tăng áp lực hoặc giảm diện tích bị ép","Tăng áp lực và diện tích bị ép theo cùng một tỉ lệ"],"a":"Tăng áp lực hoặc giảm diện tích bị ép","h":"Áp suất phụ thuộc vào áp lực và diện tích bị ép theo công thức p = F/S.","e":"Áp suất p = F/S nên tăng khi áp lực F tăng hoặc diện tích bị ép S giảm; ví dụ lưỡi dao được mài mỏng (diện tích bị ép nhỏ) để cắt dễ hơn.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Một thợ lặn xuống càng sâu trong nước thì áp suất của nước tác dụng lên người thợ lặn sẽ:","o":["Giảm dần","Không thay đổi","Lúc tăng lúc giảm","Càng lớn (tăng dần)"],"a":"Càng lớn (tăng dần)","h":"Áp suất chất lỏng phụ thuộc vào độ sâu của điểm đang xét.","e":"Trong cùng một chất lỏng, điểm càng sâu thì áp suất chất lỏng tác dụng càng lớn; vì thế thợ lặn càng xuống sâu càng chịu áp suất nước lớn.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Áp suất khí quyển tồn tại là do:","o":["Lớp không khí bao quanh Trái Đất có trọng lượng, ép lên mọi vật trên mặt đất","Gió thổi mạnh trên bề mặt Trái Đất","Mặt Trời chiếu sáng làm không khí nóng lên","Trái Đất tự quay quanh trục của nó"],"a":"Lớp không khí bao quanh Trái Đất có trọng lượng, ép lên mọi vật trên mặt đất","h":"Không khí tuy rất nhẹ nhưng vẫn có khối lượng và chịu tác dụng của trọng lực.","e":"Lớp khí quyển dày hàng nghìn kilômét có trọng lượng rất lớn, tạo ra áp suất khí quyển tác dụng lên mọi vật trên Trái Đất.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Dòng điện là:","o":["Dòng các điện tích đứng yên trong dây dẫn","Dòng các điện tích dịch chuyển có hướng","Dòng nước chảy trong ống dẫn điện","Sự dịch chuyển hỗn loạn, không theo hướng nào của các điện tích"],"a":"Dòng các điện tích dịch chuyển có hướng","h":"Chú ý hai ý then chốt: điện tích và sự dịch chuyển có hướng.","e":"Dòng điện là dòng dịch chuyển có hướng của các điện tích; trong dây dẫn kim loại, đó là các electron tự do dịch chuyển có hướng.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Một mạch điện đơn giản để thắp sáng một bóng đèn cần gồm các bộ phận thiết yếu nào?","o":["Nguồn điện, bóng đèn và ampe kế","Bóng đèn, dây dẫn và vôn kế","Nguồn điện, dây dẫn, bóng đèn và khoá điện","Nguồn điện, bóng đèn và cầu chì"],"a":"Nguồn điện, dây dẫn, bóng đèn và khoá điện","h":"Mạch phải tạo thành một vòng kín và có thiết bị để đóng, ngắt mạch.","e":"Mạch điện đơn giản gồm nguồn điện (cung cấp năng lượng), dây dẫn (nối các bộ phận), bóng đèn (thiết bị tiêu thụ điện) và khoá điện (đóng/ngắt mạch).","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Vật liệu nào sau đây dẫn điện?","o":["Thanh nhựa","Thước gỗ khô","Dây cao su","Dây đồng"],"a":"Dây đồng","h":"Các kim loại thường là vật liệu dẫn điện tốt.","e":"Đồng là kim loại nên dẫn điện tốt; nhựa, gỗ khô và cao su là các vật liệu cách điện.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong công nghiệp, người ta mạ một lớp đồng lên bề mặt một vật bằng sắt bằng cách cho dòng điện chạy qua dung dịch muối đồng. Ứng dụng này dựa trên tác dụng nào của dòng điện?","o":["Tác dụng hoá học","Tác dụng nhiệt","Tác dụng phát sáng","Tác dụng sinh lí"],"a":"Tác dụng hoá học","h":"Dòng điện đã làm biến đổi chất trong dung dịch, tạo ra lớp chất mới bám lên vật.","e":"Dòng điện chạy qua dung dịch muối đồng làm đồng tách ra và bám lên vật cần mạ; đó là tác dụng hoá học của dòng điện, được ứng dụng trong kĩ thuật mạ điện.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Khi đun một ấm nước, nước ở đáy ấm nóng lên, nhẹ đi và nổi lên trên, còn nước lạnh ở phía trên chìm xuống. Sự truyền nhiệt trong nước chủ yếu theo hình thức nào?","o":["Dẫn nhiệt","Đối lưu","Bức xạ nhiệt","Bay hơi"],"a":"Đối lưu","h":"Hình thức truyền nhiệt này gắn với sự chuyển động của dòng chất lỏng hoặc chất khí.","e":"Sự truyền nhiệt bằng các dòng chất lỏng (hoặc chất khí) chuyển động gọi là đối lưu; đây là hình thức truyền nhiệt chủ yếu trong chất lỏng và chất khí.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Nồi, xoong nấu ăn thường được làm bằng kim loại, nhưng quai cầm lại làm bằng nhựa hoặc gỗ. Cách làm này dựa trên tính chất nào?","o":["Kim loại nhẹ hơn nhựa nên nồi dễ cầm hơn","Nhựa và gỗ có giá thành rẻ hơn kim loại","Kim loại dẫn nhiệt tốt giúp nấu nhanh chín, còn nhựa và gỗ dẫn nhiệt kém giúp cầm không bị bỏng","Kim loại bền hơn nên được dùng làm phần chứa thức ăn"],"a":"Kim loại dẫn nhiệt tốt giúp nấu nhanh chín, còn nhựa và gỗ dẫn nhiệt kém giúp cầm không bị bỏng","h":"Hãy xét khả năng dẫn nhiệt của hai nhóm vật liệu được dùng.","e":"Thân nồi bằng kim loại dẫn nhiệt tốt nên nhiệt truyền nhanh vào thức ăn; quai nồi bằng nhựa hoặc gỗ dẫn nhiệt kém (cách nhiệt) nên người cầm không bị nóng tay.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Để giữ cho nước đá trong thùng lâu tan vào ngày nắng nóng, người ta thường dùng thùng xốp. Lí do chính là:","o":["Xốp có màu trắng nên phản xạ ánh sáng tốt hơn","Xốp nhẹ nên dễ di chuyển","Xốp rẻ tiền và dễ mua","Xốp dẫn nhiệt rất kém nên hạn chế được nhiệt từ bên ngoài truyền vào trong thùng"],"a":"Xốp dẫn nhiệt rất kém nên hạn chế được nhiệt từ bên ngoài truyền vào trong thùng","h":"Hãy nghĩ về khả năng truyền nhiệt của vật liệu làm thùng.","e":"Xốp là chất dẫn nhiệt kém (cách nhiệt tốt), làm chậm sự truyền nhiệt từ môi trường nóng bên ngoài vào nước đá, nhờ đó nước đá lâu tan hơn.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Hệ vận động của cơ thể người gồm các cơ quan nào?","o":["Xương, khớp và cơ","Tim, mạch máu và máu","Não, tuỷ sống và dây thần kinh","Phổi, khí quản và phế quản"],"a":"Xương, khớp và cơ","h":"Đây là hệ cơ quan giúp cơ thể di chuyển và vận động.","e":"Hệ vận động gồm bộ xương, các khớp nối giữa các xương và hệ cơ bám vào xương; chúng phối hợp với nhau giúp cơ thể vận động.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong hệ tuần hoàn, động mạch đảm nhiệm chức năng nào?","o":["Dẫn máu từ các cơ quan trở về tim","Dẫn máu từ tim đến các cơ quan trong cơ thể","Trao đổi chất trực tiếp với các tế bào","Lọc máu để tạo thành nước tiểu"],"a":"Dẫn máu từ tim đến các cơ quan trong cơ thể","h":"Hãy nhớ chiều đi của máu: động mạch đưa máu ra khỏi tim.","e":"Tim co bóp đẩy máu vào các động mạch để đưa máu đi nuôi cơ thể; còn tĩnh mạch dẫn máu từ các cơ quan trở về tim.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Sự trao đổi khí giữa cơ thể và môi trường trong hệ hô hấp diễn ra chủ yếu tại:","o":["Khí quản","Phế quản","Các phế nang trong phổi","Khoang mũi"],"a":"Các phế nang trong phổi","h":"Đây là các túi khí rất nhỏ, xung quanh có mạng mao mạch dày đặc.","e":"Phế nang có thành mỏng và được bao quanh bởi mạng mao mạch dày đặc, là nơi oxygen khuếch tán vào máu và carbon dioxide từ máu đi ra ngoài.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong hệ tiêu hoá, sau khi thức ăn được biến đổi, các chất dinh dưỡng được hấp thụ vào máu chủ yếu ở:","o":["Dạ dày","Thực quản","Ruột già","Ruột non"],"a":"Ruột non","h":"Cơ quan này rất dài, có nhiều nếp gấp và lông ruột làm tăng diện tích hấp thụ.","e":"Ruột non là nơi hoàn tất quá trình tiêu hoá và hấp thụ phần lớn chất dinh dưỡng vào máu nhờ diện tích bề mặt hấp thụ rất lớn.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Cơ quan nào của hệ bài tiết lọc máu để tạo thành nước tiểu?","o":["Thận","Bóng đái (bàng quang)","Ống dẫn nước tiểu","Gan"],"a":"Thận","h":"Nước tiểu được tạo ra ở cơ quan này rồi mới theo ống dẫn xuống bóng đái.","e":"Thận lọc các chất cặn bã và nước thừa trong máu để tạo thành nước tiểu; bóng đái chỉ là nơi chứa nước tiểu trước khi thải ra ngoài.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Hệ thần kinh của người gồm các bộ phận chính nào?","o":["Chỉ gồm não và tuỷ sống","Não, tuỷ sống và các dây thần kinh","Não và các giác quan","Tuỷ sống và các cơ"],"a":"Não, tuỷ sống và các dây thần kinh","h":"Ngoài bộ phận trung ương còn có hệ thống dây dẫn truyền tín hiệu đi khắp cơ thể.","e":"Hệ thần kinh gồm não và tuỷ sống (trung ương thần kinh) cùng hệ thống dây thần kinh toả đi khắp cơ thể, giúp điều khiển và phối hợp mọi hoạt động sống.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Bệnh đái tháo đường thường liên quan đến hormone insulin. Insulin do cơ quan nào tiết ra?","o":["Tuyến giáp ở cổ","Gan","Tuyến tuỵ","Thận"],"a":"Tuyến tuỵ","h":"Cơ quan này vừa tiết dịch tiêu hoá, vừa tiết hormone trực tiếp vào máu.","e":"Tuyến tuỵ tiết hormone insulin giúp điều hoà lượng đường trong máu; khi cơ thể thiếu insulin hoặc insulin hoạt động kém, đường huyết tăng cao gây bệnh đái tháo đường.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Tập hợp các cá thể cùng loài, cùng sống trong một khu vực nhất định, ở một thời điểm nhất định và có khả năng sinh sản với nhau được gọi là:","o":["Quần xã sinh vật","Hệ sinh thái","Một loài sinh vật","Quần thể sinh vật"],"a":"Quần thể sinh vật","h":"Chú ý hai điều kiện: cùng loài và cùng sống trong một khu vực.","e":"Quần thể sinh vật là tập hợp các cá thể cùng loài sống trong cùng một khu vực nhất định; còn quần xã gồm nhiều quần thể thuộc các loài khác nhau.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trong một khu rừng, cùng sinh sống có các quần thể thông, sồi, chim sẻ, sóc, nấm và nhiều loài khác, chúng tác động qua lại với nhau. Tập hợp tất cả các quần thể sinh vật đó được gọi là:","o":["Quần xã sinh vật","Quần thể sinh vật","Chuỗi thức ăn","Một hệ cơ quan"],"a":"Quần xã sinh vật","h":"Khi có nhiều quần thể của nhiều loài khác nhau cùng chung sống, ta dùng một khái niệm rộng hơn quần thể.","e":"Quần xã sinh vật là tập hợp nhiều quần thể thuộc các loài khác nhau cùng sống trong một khu vực và có mối quan hệ tác động qua lại với nhau.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Một hệ sinh thái hoàn chỉnh bao gồm hai thành phần là:","o":["Chỉ gồm các sinh vật sống trong khu vực","Quần xã sinh vật và môi trường sống của chúng (các yếu tố vô sinh)","Chỉ gồm các yếu tố vô sinh như đất, nước, ánh sáng","Sinh vật sản xuất và sinh vật phân giải"],"a":"Quần xã sinh vật và môi trường sống của chúng (các yếu tố vô sinh)","h":"Hệ sinh thái là khái niệm rộng hơn quần xã vì còn tính thêm một thành phần nữa.","e":"Hệ sinh thái gồm quần xã sinh vật và môi trường sống của chúng (đất, nước, không khí, ánh sáng...) luôn tác động qua lại lẫn nhau.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Cho chuỗi thức ăn: Cỏ → Châu chấu → Ếch → Rắn. Trong chuỗi này, châu chấu đóng vai trò là:","o":["Sinh vật sản xuất","Sinh vật phân giải","Sinh vật tiêu thụ","Sinh vật tự dưỡng"],"a":"Sinh vật tiêu thụ","h":"Châu chấu không tự tạo ra chất hữu cơ mà ăn trực tiếp sinh vật đứng đầu chuỗi.","e":"Cỏ là sinh vật sản xuất; châu chấu ăn cỏ nên là sinh vật tiêu thụ (bậc 1), ếch là sinh vật tiêu thụ bậc 2 và rắn là sinh vật tiêu thụ bậc 3.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Hành động nào sau đây góp phần bảo vệ đa dạng sinh học và môi trường sống của sinh vật?","o":["Săn bắt các loài động vật quý hiếm để buôn bán","Chặt phá rừng đầu nguồn để lấy đất canh tác","Xả chất thải chưa qua xử lí ra sông, hồ","Trồng rừng, bảo vệ rừng và xây dựng các khu bảo tồn thiên nhiên"],"a":"Trồng rừng, bảo vệ rừng và xây dựng các khu bảo tồn thiên nhiên","h":"Hãy chọn hành động giúp các loài sinh vật giữ được nơi sống của chúng.","e":"Trồng và bảo vệ rừng, xây dựng khu bảo tồn thiên nhiên giúp gìn giữ môi trường sống, bảo vệ các loài sinh vật khỏi nguy cơ suy giảm và tuyệt chủng, tức là bảo vệ đa dạng sinh học.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Oxide là hợp chất gồm hai nguyên tố hoá học, trong đó có một nguyên tố là:","o":["Hydrogen","Oxygen","Carbon","Nitrogen"],"a":"Oxygen","h":"Tên gọi 'oxide' gắn liền với nguyên tố nào?","e":"Oxide là hợp chất của oxygen với một nguyên tố khác, ví dụ CO2, CaO. Trong đó CO2 là oxide acid, còn CaO là oxide base.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Đốt cháy hoàn toàn 6 g carbon trong khí oxygen theo phương trình: C + O2 → CO2. Biết 6 g carbon tương ứng 0,5 mol và tỉ lệ mol C : O2 = 1 : 1, khối lượng khí oxygen cần dùng là:","o":["8 g","32 g","16 g","44 g"],"a":"16 g","h":"Số mol O2 cần dùng bằng số mol C; khối lượng mol của O2 là 32 g/mol.","e":"n(C) = 0,5 mol, theo tỉ lệ 1 : 1 nên n(O2) = 0,5 mol. Khối lượng oxygen cần dùng: m(O2) = 0,5 × 32 = 16 g.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Khi muối tác dụng với dung dịch acid (ví dụ CaCO3 tác dụng với HCl), sản phẩm tạo thành thường là:","o":["Muối mới và acid mới","Muối mới và khí oxygen","Kim loại mới và muối mới","Base mới và nước"],"a":"Muối mới và acid mới","h":"Hãy nhớ quy tắc chung của phản ứng giữa muối và acid.","e":"Muối + acid → muối mới + acid mới. Ví dụ: CaCO3 + 2HCl → CaCl2 + H2O + CO2 (acid mới tạo thành yếu, phân huỷ thành H2O và CO2 nên thấy khí thoát ra).","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Phân bón hoá học cung cấp cho cây trồng chủ yếu ba nguyên tố dinh dưỡng nào sau đây?","o":["Carbon, hydrogen, oxygen (C, H, O)","Calcium, magnesium, sulfur (Ca, Mg, S)","Iron, zinc, copper (Fe, Zn, Cu)","Nitrogen, phosphorus, potassium (N, P, K)"],"a":"Nitrogen, phosphorus, potassium (N, P, K)","h":"Ba nguyên tố này thường được ghi ngay trên bao bì phân bón.","e":"Phân bón hoá học chủ yếu cung cấp N (đạm), P (lân), K (kali) — ba nguyên tố dinh dưỡng đa lượng quan trọng nhất cho cây trồng.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Phản ứng hoá học sẽ xảy ra nhanh hơn khi ta:","o":["Giảm nhiệt độ và giảm nồng độ chất phản ứng","Tăng nhiệt độ hoặc tăng nồng độ chất phản ứng","Để hỗn hợp đứng yên, không khuấy trộn","Pha loãng dung dịch chất phản ứng"],"a":"Tăng nhiệt độ hoặc tăng nồng độ chất phản ứng","h":"Nghĩ đến việc đun nóng giúp thức ăn chín nhanh hơn.","e":"Tăng nhiệt độ hoặc tăng nồng độ làm các hạt chất phản ứng va chạm với nhau nhiều và mạnh hơn, nên tốc độ phản ứng tăng lên (SGK KHTN 8, Bài 7).","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Để phân huỷ hydrogen peroxide (H2O2) nhanh hơn, người ta thêm vào một ít manganese dioxide (MnO2). MnO2 đóng vai trò chất xúc tác, nghĩa là MnO2:","o":["Bị phân huỷ cùng với H2O2","Là sản phẩm chính của phản ứng","Làm phản ứng xảy ra nhanh hơn nhưng không bị biến đổi sau phản ứng","Làm tăng khối lượng oxygen thu được"],"a":"Làm phản ứng xảy ra nhanh hơn nhưng không bị biến đổi sau phản ứng","h":"Sau phản ứng, lượng MnO2 vẫn còn nguyên như ban đầu.","e":"Chất xúc tác làm thay đổi (thường là tăng) tốc độ phản ứng nhưng bản thân không bị biến đổi về lượng và tính chất sau phản ứng: 2H2O2 —(MnO2)→ 2H2O + O2.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khí carbon dioxide (CO2) có khối lượng mol M = 44 g/mol. Tỉ khối của khí CO2 so với khí hydrogen được tính bằng dCO2/H2 = 44/2 và bằng:","o":["22","44","11","88"],"a":"22","h":"Thực hiện phép chia 44 : 2.","e":"Tỉ khối của khí A so với hydrogen: dA/H2 = MA/2. Với CO2: dCO2/H2 = 44/2 = 22, nghĩa là CO2 nặng gấp 22 lần khí hydrogen.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Lực đẩy Archimedes tác dụng lên một vật nhúng trong chất lỏng có phương và chiều như thế nào?","o":["Phương ngang, chiều từ phải sang trái","Phương thẳng đứng, chiều hướng xuống","Phương xiên, chiều hướng ra ngoài","Phương thẳng đứng, chiều hướng lên"],"a":"Phương thẳng đứng, chiều hướng lên","h":"Chính lực này đẩy vật nổi lên trên mặt nước.","e":"Lực đẩy Archimedes có phương thẳng đứng, chiều hướng từ dưới lên trên, ngược chiều với trọng lực tác dụng lên vật.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Thả một vật vào trong chất lỏng. Vật sẽ chìm xuống khi:","o":["Lực đẩy Archimedes lớn hơn trọng lượng của vật","Lực đẩy Archimedes nhỏ hơn trọng lượng của vật","Lực đẩy Archimedes bằng trọng lượng của vật","Vật có thể tích càng lớn"],"a":"Lực đẩy Archimedes nhỏ hơn trọng lượng của vật","h":"So sánh lực đẩy lên và lực hút xuống (trọng lượng của vật).","e":"Khi lực đẩy Archimedes nhỏ hơn trọng lượng, hợp lực hướng xuống nên vật chìm. Điều này thường xảy ra khi khối lượng riêng của vật lớn hơn khối lượng riêng của chất lỏng.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Tác dụng làm quay của một lực đối với vật (moment lực) sẽ càng lớn khi:","o":["Lực tác dụng càng nhỏ","Cánh tay đòn càng ngắn","Lực càng lớn hoặc cánh tay đòn càng dài","Lực tác dụng đúng vào trục quay"],"a":"Lực càng lớn hoặc cánh tay đòn càng dài","h":"Dùng cờ lê dài sẽ vặn ốc dễ hơn cờ lê ngắn.","e":"Moment lực càng lớn khi lực càng lớn và cánh tay đòn (khoảng cách từ trục quay đến đường tác dụng của lực) càng dài; vì vậy dùng cờ lê dài sẽ dễ vặn ốc hơn.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Dụng cụ nào sau đây là ứng dụng của đòn bẩy giúp ta được lợi về lực?","o":["Búa nhổ đinh","Cầu trượt trong công viên","Bánh xe của xe đạp","Nam châm hút đinh sắt"],"a":"Búa nhổ đinh","h":"Dụng cụ này có một điểm tựa và giúp tháo vật nặng ra dễ dàng.","e":"Búa nhổ đinh là đòn bẩy cho lợi về lực; xe cút kít, cái mở nắp chai cũng vậy — chỉ cần một lực nhỏ tác dụng ở xa điểm tựa cũng nhổ được chiếc đinh lớn.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Cọ xát một chiếc thước nhựa vào tóc khô rồi đưa thước lại gần các mẩu giấy nhỏ, thước hút được các mẩu giấy. Hiện tượng này xảy ra vì:","o":["Thước nhựa trở thành nam châm","Thước nhựa nóng lên làm giấy nhẹ đi","Luồng không khí đẩy giấy về phía thước","Thước nhựa bị nhiễm điện do cọ xát"],"a":"Thước nhựa bị nhiễm điện do cọ xát","h":"Sau khi cọ xát, chiếc thước mang điện tích.","e":"Khi cọ xát, thước nhựa bị nhiễm điện (mang điện tích) nên có khả năng hút các vật nhỏ, nhẹ như mẩu giấy.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Hiệu điện thế được đo bằng vôn kế, đơn vị là vôn (V). Cường độ dòng điện được đo bằng dụng cụ nào, với đơn vị nào?","o":["Vôn kế — vôn (V)","Ampe kế — ampe (A)","Ôm kế — ôm","Nhiệt kế — độ C"],"a":"Ampe kế — ampe (A)","h":"Tên dụng cụ gợi ý ngay tên đơn vị của cường độ dòng điện.","e":"Cường độ dòng điện được đo bằng ampe kế, đơn vị là ampe (A); hiệu điện thế được đo bằng vôn kế, đơn vị là vôn (V).","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Da của người có những vai trò quan trọng nào sau đây?","o":["Chỉ có vai trò tạo màu sắc cho cơ thể","Chỉ là nơi chứa các đầu dây thần kinh","Bảo vệ cơ thể khỏi tác nhân bên ngoài và điều hoà thân nhiệt","Sản xuất ra máu cho cơ thể"],"a":"Bảo vệ cơ thể khỏi tác nhân bên ngoài và điều hoà thân nhiệt","h":"Khi trời nóng, da tiết mồ hôi để làm gì?","e":"Da bao bọc và bảo vệ cơ thể khỏi các tác nhân bên ngoài, đồng thời giúp điều hoà thân nhiệt: khi nóng, da tiết mồ hôi và giãn mạch máu để thải nhiệt; khi lạnh, mạch máu dưới da co lại để giữ nhiệt.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Máu, nước mô và bạch huyết tạo thành môi trường trong của cơ thể. Cơ thể luôn giữ môi trường trong ổn định (về nhiệt độ, độ pH, nồng độ các chất...) — hiện tượng này được gọi là:","o":["Cân bằng nội môi","Trao đổi chất với môi trường ngoài","Sinh trưởng và phát triển","Cảm ứng của cơ thể"],"a":"Cân bằng nội môi","h":"Thuật ngữ này nói về sự ổn định ở bên trong cơ thể.","e":"Cân bằng nội môi là sự duy trì ổn định của môi trường trong cơ thể; nhờ đó các tế bào mới hoạt động bình thường dù điều kiện môi trường ngoài thay đổi.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Nhân tố sinh thái nào sau đây thuộc nhóm nhân tố VÔ SINH?","o":["Cây xanh quang hợp trong rừng","Vi sinh vật sống trong đất","Động vật ăn cỏ trong đồng cỏ","Ánh sáng, nhiệt độ và nước"],"a":"Ánh sáng, nhiệt độ và nước","h":"Nhân tố vô sinh là các yếu tố không sống của môi trường.","e":"Nhân tố vô sinh gồm ánh sáng, nhiệt độ, nước, không khí, đất...; còn cây xanh, vi sinh vật, động vật là các nhân tố hữu sinh (sinh vật sống).","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Sự thụ tinh ở người được hiểu là:","o":["Quá trình trứng rụng khỏi buồng trứng","Sự kết hợp của tinh trùng với trứng tạo thành hợp tử","Quá trình phôi bám vào thành tử cung","Sự phát triển của thai nhi trong tử cung"],"a":"Sự kết hợp của tinh trùng với trứng tạo thành hợp tử","h":"Kết quả của quá trình này là tế bào đầu tiên của một cơ thể mới.","e":"Thụ tinh là sự kết hợp của tinh trùng (của bố) và trứng (của mẹ) tạo thành hợp tử — tế bào đầu tiên sẽ phát triển thành phôi và thai nhi (SGK KHTN 8, Bài 40).","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Nội năng của một vật là gì?","o":["Chỉ là thế năng trọng trường của vật so với mặt đất","Tổng động năng và thế năng của các phân tử cấu tạo nên vật","Chỉ là nhiệt lượng mà vật thu vào từ bên ngoài","Khối lượng của vật nhân với nhiệt độ của vật"],"a":"Tổng động năng và thế năng của các phân tử cấu tạo nên vật","h":"Hãy nghĩ đến các phân tử cấu tạo nên vật: chúng luôn chuyển động và tương tác với nhau.","e":"Nội năng của một vật là tổng động năng và thế năng của các phân tử cấu tạo nên vật. Khi nhiệt độ của vật tăng, các phân tử chuyển động nhanh hơn nên nội năng của vật tăng lên.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Khi xây cầu thép hoặc đặt đường ray xe lửa, người ta luôn chừa lại những khe hở nhỏ giữa các đoạn thép. Việc làm này là để làm gì?","o":["Để tiết kiệm thép khi xây dựng","Để nước mưa chảy thoát xuống dưới cầu","Để thép có chỗ giãn nở khi trời nóng, tránh làm cầu và đường ray bị cong vênh, nứt gãy","Để cầu nhẹ hơn và xe chạy êm hơn"],"a":"Để thép có chỗ giãn nở khi trời nóng, tránh làm cầu và đường ray bị cong vênh, nứt gãy","h":"Hãy nhớ tính chất của chất rắn khi nhiệt độ tăng lên.","e":"Chất rắn nở ra khi nóng lên và co lại khi lạnh đi. Nếu không chừa khe hở, vào ngày nắng nóng các đoạn thép nở ra sẽ xô đẩy nhau làm cầu, đường ray cong vênh hoặc nứt gãy, gây nguy hiểm.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Một quả cầu kim loại lọt qua được một vòng kim loại khi quả cầu còn lạnh. Sau khi nung nóng quả cầu lên, quả cầu không còn lọt qua vòng được nữa. Giải thích đúng hiện tượng này là:","o":["Khi nung nóng, quả cầu nhẹ đi nên bị vòng giữ lại","Khi nung nóng, quả cầu nở ra, thể tích tăng lên nên không lọt qua vòng","Khi nung nóng, vòng kim loại co lại làm lỗ vòng nhỏ đi","Khi nung nóng, quả cầu bị mềm ra và biến dạng"],"a":"Khi nung nóng, quả cầu nở ra, thể tích tăng lên nên không lọt qua vòng","h":"Chất rắn thay đổi kích thước thế nào khi nhiệt độ tăng?","e":"Khi được nung nóng, quả cầu kim loại nở vì nhiệt: kích thước và thể tích của quả cầu tăng lên, lớn hơn lỗ của vòng nên không lọt qua được nữa. Khi để nguội, quả cầu co lại và lại lọt qua vòng.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Khi sử dụng hoá chất trong phòng thực hành, việc làm đầu tiên và quan trọng để đảm bảo an toàn là gì?","o":["Đọc kĩ nhãn, nhận biết các ký hiệu cảnh báo nguy hiểm (dễ cháy, ăn mòn, độc hại) trên lọ hoá chất","Nếm thử để biết hoá chất có vị gì","Ngửi trực tiếp sát miệng lọ để đoán tên hoá chất","Đổ các hoá chất thừa vào chung một lọ cho gọn"],"a":"Đọc kĩ nhãn, nhận biết các ký hiệu cảnh báo nguy hiểm (dễ cháy, ăn mòn, độc hại) trên lọ hoá chất","h":"Hãy quan sát trên lọ hoá chất có những ký hiệu hình vẽ cảnh báo nguy hiểm.","e":"Trên nhãn các lọ hoá chất có các ký hiệu cảnh báo như chất dễ cháy, chất ăn mòn, chất độc. Đọc kĩ nhãn hoá chất trước khi dùng giúp nhận biết mức độ nguy hiểm và cách sử dụng an toàn, tránh tai nạn trong phòng thực hành.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Dấu hiệu dễ nhận biết nhất của một dung dịch acid khi dùng giấy quỳ tím là:","o":["Làm giấy quỳ tím chuyển sang màu đỏ","Làm giấy quỳ tím chuyển sang màu xanh","Làm giấy quỳ tím mất màu hoàn toàn","Không làm giấy quỳ tím đổi màu"],"a":"Làm giấy quỳ tím chuyển sang màu đỏ","h":"Hãy nhớ: acid làm quỳ tím hoá đỏ, base làm quỳ tím hoá xanh.","e":"Dung dịch acid làm quỳ tím hoá đỏ, có vị chua; ngược lại dung dịch base làm quỳ tím hoá xanh. Dựa vào sự đổi màu của quỳ tím, ta nhận biết được một dung dịch có tính acid hay tính base.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Sinh quyển trên Trái Đất là:","o":["Chỉ gồm các khu rừng nguyên sinh trên Trái Đất","Toàn bộ lớp vỏ của Trái Đất nơi có sinh vật sinh sống (gồm tầng thấp của khí quyển, toàn bộ thuỷ quyển và lớp trên của thạch quyển)","Chỉ gồm phần nước của các đại dương","Chỉ gồm lớp đất trồng trên bề mặt Trái Đất"],"a":"Toàn bộ lớp vỏ của Trái Đất nơi có sinh vật sinh sống (gồm tầng thấp của khí quyển, toàn bộ thuỷ quyển và lớp trên của thạch quyển)","h":"Hãy nghĩ đến mọi nơi trên Trái Đất có sự sống: trên không, trong nước và trong đất.","e":"Sinh quyển là toàn bộ lớp vỏ của Trái Đất có sinh vật sinh sống, bao gồm tầng thấp của khí quyển, toàn bộ thuỷ quyển (ao, hồ, biển) và phần trên của thạch quyển (đất, đá). Sinh quyển là hệ sinh thái lớn nhất trên Trái Đất.","t":"khtn-lop8","g":8,"l":"nhe-nhang"},{"p":"Trạng thái cân bằng tự nhiên của quần xã sinh vật được hiểu là:","o":["Số lượng cá thể của các quần thể trong quần xã luôn dao động quanh một mức ổn định nhờ các mối quan hệ giữa các loài","Mọi loài trong quần xã đều tăng số lượng mãi mãi","Trong quần xã không có loài nào chết đi","Số lượng cá thể của các loài hoàn toàn do con người quyết định"],"a":"Số lượng cá thể của các quần thể trong quần xã luôn dao động quanh một mức ổn định nhờ các mối quan hệ giữa các loài","h":"Hãy nghĩ về quan hệ số lượng giữa con mồi và động vật ăn thịt trong một khu rừng.","e":"Cân bằng tự nhiên là trạng thái ổn định tự nhiên của quần xã, trong đó số lượng cá thể của mỗi quần thể dao động quanh một mức nhất định. Ví dụ: khi số lượng thỏ tăng, số lượng cáo (ăn thỏ) cũng tăng theo, làm số thỏ giảm xuống, và ngược lại.","t":"khtn-lop8","g":8,"l":"thu-thach"},{"p":"Tính chất vật lí nào sau đây là tính chất chung của hầu hết các kim loại?","o":["Dẫn điện và dẫn nhiệt tốt","Dễ tan trong nước","Có màu đen sẫm","Nhẹ hơn nước và nổi trên mặt nước"],"a":"Dẫn điện và dẫn nhiệt tốt","h":"Hãy nhớ vì sao dây điện và nồi nấu thường làm bằng kim loại.","e":"Kim loại nói chung đều dẫn điện, dẫn nhiệt tốt, có ánh kim và tính dẻo; đây là các tính chất vật lí chung của kim loại.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Nhờ tính chất nào mà nhôm có thể được dát mỏng thành lá nhôm bọc thực phẩm hoặc kéo thành sợi?","o":["Tính cứng","Tính dẻo","Tính giòn","Tính nhiễm từ"],"a":"Tính dẻo","h":"Tính chất này cho phép kim loại bị kéo giãn, dát mỏng mà không vỡ.","e":"Kim loại có tính dẻo nên có thể kéo sợi, dát mỏng; nhôm dát mỏng được dùng làm lá bọc thực phẩm, giấy bạc.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi đốt cháy sắt trong khí oxygen, sản phẩm tạo thành thuộc loại chất nào?","o":["Muối sắt","Khí hydrogen","Oxide của sắt","Acid"],"a":"Oxide của sắt","h":"Kim loại tác dụng với oxygen thường tạo thành hợp chất của kim loại với oxygen.","e":"Kim loại tác dụng với oxygen tạo thành oxide; sắt cháy trong oxygen tạo oxide sắt từ (Fe3O4).","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Cho kẽm (Zn) tác dụng với dung dịch hydrochloric acid (HCl) loãng, khí thoát ra là khí nào?","o":["Oxygen","Carbon dioxide","Nitrogen","Hydrogen"],"a":"Hydrogen","h":"Nhiều kim loại tác dụng với dung dịch acid sẽ giải phóng một khí nhẹ, cháy được trong không khí.","e":"Kim loại đứng trước hydrogen trong dãy hoạt động (như Zn) tác dụng với dung dịch acid tạo thành muối và giải phóng khí hydrogen.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Để sử dụng bếp gas trong gia đình an toàn và tiết kiệm, việc làm nào sau đây là đúng?","o":["Đảm bảo gas cháy hoàn toàn với ngọn lửa xanh, thông gió tốt và khoá van bình gas sau khi nấu","Để bếp gas cháy liên tục cả ngày cho ấm nhà","Dùng xăng thay cho gas khi hết gas","Đậy kín hết cửa khi đun nấu để giữ nhiệt"],"a":"Đảm bảo gas cháy hoàn toàn với ngọn lửa xanh, thông gió tốt và khoá van bình gas sau khi nấu","h":"Hãy nghĩ đến điều kiện để nhiên liệu cháy hoàn toàn và nguy cơ rò rỉ khí gas.","e":"Nhiên liệu cháy hoàn toàn khi có đủ oxygen cho nhiệt lượng cao và ít khí độc; khoá van sau khi dùng và giữ thông gió giúp tránh rò rỉ, ngộ độc khí gas.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Trong dãy hoạt động hoá học của kim loại, kim loại nào sau đây hoạt động hoá học mạnh nhất?","o":["Sắt (Fe)","Kẽm (Zn)","Kali (K)","Đồng (Cu)"],"a":"Kali (K)","h":"Dãy hoạt động bắt đầu bằng các kim loại kiềm phản ứng rất mạnh với nước.","e":"Đầu dãy hoạt động hoá học là K, Na, Ca... nên kali là kim loại hoạt động mạnh nhất trong các kim loại đã cho.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Dãy kim loại nào sau đây được sắp xếp theo chiều hoạt động hoá học GIẢM dần?","o":["Cu, Fe, Zn, Mg, K","K, Mg, Zn, Fe, Cu","Fe, Cu, Zn, K, Mg","Zn, K, Fe, Mg, Cu"],"a":"K, Mg, Zn, Fe, Cu","h":"Hãy nhớ thứ tự đầu dãy: K, Na, Ca, Mg, Al, Zn, Fe... và Cu đứng gần cuối dãy.","e":"Theo dãy hoạt động hoá học, hoạt động giảm dần theo thứ tự K > Mg > Zn > Fe > Cu nên chỉ dãy này sắp xếp đúng.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Vì sao đồng (Cu) không tác dụng với dung dịch acid loãng để giải phóng khí hydrogen?","o":["Vì đồng không dẫn điện","Vì đồng là kim loại cứng nhất","Vì đồng tan hoàn toàn trong nước","Vì đồng đứng sau hydrogen trong dãy hoạt động hoá học của kim loại"],"a":"Vì đồng đứng sau hydrogen trong dãy hoạt động hoá học của kim loại","h":"Chỉ những kim loại đứng ở vị trí nhất định so với hydrogen mới đẩy được hydrogen ra khỏi dung dịch acid.","e":"Kim loại đứng sau hydrogen trong dãy hoạt động (như Cu, Ag) không đẩy được hydrogen ra khỏi dung dịch acid loãng nên không giải phóng khí H2.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Nhôm nhẹ và khá bền trong không khí, được dùng làm vỏ máy bay và đồ gia dụng, chủ yếu là nhờ:","o":["Nhôm là kim loại cứng nhất","Nhôm không dẫn nhiệt","Nhôm rẻ hơn mọi kim loại khác","Lớp màng oxide mỏng, bền bao phủ bề mặt bảo vệ nhôm bên trong"],"a":"Lớp màng oxide mỏng, bền bao phủ bề mặt bảo vệ nhôm bên trong","h":"Bề mặt nhôm luôn có một lớp chất mỏng sinh ra khi nhôm gặp không khí.","e":"Nhôm phản ứng với oxygen tạo lớp aluminium oxide mỏng, bền, bám chắc, ngăn nhôm bên trong bị ăn mòn tiếp, đồng thời nhôm nhẹ nên hợp làm vỏ máy bay.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"So với gang, thép có ưu điểm nổi bật nào?","o":["Mềm và dẻo hơn gang rất nhiều","Giòn hơn gang","Cứng và có tính đàn hồi tốt hơn gang","Không bị gỉ trong mọi môi trường"],"a":"Cứng và có tính đàn hồi tốt hơn gang","h":"Gang chứa nhiều carbon hơn nên giòn; thép được luyện lại để cải thiện tính chất.","e":"Thép có hàm lượng carbon thấp hơn gang nên cứng và đàn hồi tốt hơn, được dùng làm khung nhà, cầu, dao kéo; gang giòn hơn nên hay dùng đúc chi tiết.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Gang và thép đều là hợp kim của sắt với nguyên tố nào là chủ yếu?","o":["Oxygen","Carbon","Lưu huỳnh (sulfur)","Nitơ (nitrogen)"],"a":"Carbon","h":"Nguyên tố này cũng là thành phần của than đá, than chì.","e":"Gang và thép là hợp kim của sắt với carbon (kèm một số nguyên tố khác); tỉ lệ carbon quyết định tính chất của từng loại.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Kim cương rất cứng còn than chì lại mềm, dù cả hai đều cấu tạo từ nguyên tố carbon. Kim cương và than chì được gọi là gì của carbon?","o":["Các dạng thù hình","Các đồng vị","Các oxide","Các muối carbonate"],"a":"Các dạng thù hình","h":"Cùng một nguyên tố nhưng tồn tại ở nhiều dạng đơn chất khác nhau với tính chất khác nhau.","e":"Một nguyên tố có thể tồn tại ở nhiều dạng đơn chất khác nhau gọi là các dạng thù hình; carbon có các dạng thù hình như kim cương, than chì, than vô định hình.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Hợp chất nào sau đây là hợp chất hữu cơ?","o":["Carbon dioxide (CO2)","Methane (CH4)","Calcium carbonate (CaCO3)","Carbon monoxide (CO)"],"a":"Methane (CH4)","h":"Hãy nhớ các ngoại lệ: một số hợp chất chứa carbon như CO, CO2, muối carbonate không thuộc hợp chất hữu cơ.","e":"Hợp chất hữu cơ là hợp chất của carbon, trừ một số ngoại lệ như CO, CO2, muối carbonate, carbide; CH4 là hợp chất hữu cơ đơn giản nhất.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Methane (CH4) là thành phần chính của loại khí nào?","o":["Không khí","Khí oxygen nguyên chất","Khí nitrogen","Khí thiên nhiên (và khí biogas)"],"a":"Khí thiên nhiên (và khí biogas)","h":"Loại khí này được khai thác từ mỏ khí và cũng sinh ra khi ủ phân, rác hữu cơ.","e":"Khí thiên nhiên và khí biogas đều chứa chủ yếu methane (CH4), là nhiên liệu cháy toả nhiều nhiệt.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Động năng của một vật phụ thuộc vào những yếu tố nào?","o":["Khối lượng và tốc độ của vật","Chỉ phụ thuộc vào độ cao của vật","Màu sắc của vật","Nhiệt độ của vật"],"a":"Khối lượng và tốc độ của vật","h":"Vật càng nặng và chuyển động càng nhanh thì khi va chạm càng mạnh.","e":"Động năng của vật phụ thuộc vào khối lượng và tốc độ: vật có khối lượng càng lớn, chuyển động càng nhanh thì động năng càng lớn.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Hai ô tô có cùng khối lượng. Ô tô A chạy với tốc độ gấp đôi ô tô B. So sánh động năng của hai xe, ta có:","o":["Động năng của hai xe bằng nhau","Động năng của xe A nhỏ hơn động năng của xe B","Động năng của xe A lớn hơn động năng của xe B","Xe B không có động năng"],"a":"Động năng của xe A lớn hơn động năng của xe B","h":"Tốc độ tăng thì động năng tăng theo.","e":"Động năng phụ thuộc vào tốc độ nên xe chạy nhanh hơn (gấp đôi tốc độ) có động năng lớn hơn; chính xác thì động năng tăng gấp bốn lần.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Thế năng trọng trường của một vật càng lớn khi:","o":["Vật càng nhẹ và ở càng thấp","Vật chuyển động càng chậm","Vật có khối lượng càng lớn và được đặt ở vị trí càng cao","Vật có màu càng sáng"],"a":"Vật có khối lượng càng lớn và được đặt ở vị trí càng cao","h":"Hãy liên hệ với quả nặng của búa máy đóng cọc: nâng càng cao, đóng càng mạnh.","e":"Thế năng trọng trường phụ thuộc vào khối lượng của vật và độ cao của vật so với mốc tính thế năng; vật càng nặng, ở càng cao thì thế năng càng lớn.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Công cơ học chỉ được sinh ra khi nào?","o":["Khi có lực tác dụng lên vật và vật chuyển dời theo phương của lực","Chỉ cần có lực tác dụng, vật không cần chuyển động","Khi vật chuyển động đều mà không có lực nào tác dụng","Bất cứ khi nào ta chạm vào vật"],"a":"Khi có lực tác dụng lên vật và vật chuyển dời theo phương của lực","h":"Một người cố đẩy chiếc tủ nặng nhưng tủ không nhúc nhích thì có sinh công không?","e":"Công cơ học chỉ sinh ra khi lực tác dụng làm vật chuyển dời theo phương của lực; đẩy tủ mà tủ không chuyển động thì không sinh công cơ học.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Muốn nam châm điện hút được nhiều đinh sắt hơn, ta có thể làm gì?","o":["Giảm cường độ dòng điện xuống mức nhỏ nhất","Tháo bỏ lõi sắt non trong cuộn dây","Ngắt dòng điện khỏi cuộn dây","Tăng cường độ dòng điện qua cuộn dây hoặc tăng số vòng dây của cuộn dây"],"a":"Tăng cường độ dòng điện qua cuộn dây hoặc tăng số vòng dây của cuộn dây","h":"Lực hút của nam châm điện gắn liền với dòng điện chạy trong cuộn dây quấn quanh lõi sắt.","e":"Nam châm điện mạnh lên khi cường độ dòng điện lớn hơn hoặc số vòng dây nhiều hơn (và có lõi sắt non); ngắt điện thì nam châm điện mất từ tính.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Dòng điện cảm ứng xuất hiện trong một cuộn dây dẫn kín khi nào?","o":["Khi cuộn dây và nam châm cùng đứng yên","Khi số đường sức từ xuyên qua cuộn dây biến thiên (thay đổi theo thời gian)","Khi cuộn dây được hở mạch","Khi không có từ trường xung quanh cuộn dây"],"a":"Khi số đường sức từ xuyên qua cuộn dây biến thiên (thay đổi theo thời gian)","h":"Thí nghiệm đưa nam châm lại gần hoặc ra xa cuộn dây nối với điện kế cho thấy kim điện kế lệch.","e":"Hiện tượng cảm ứng điện từ: khi số đường sức từ qua cuộn dây kín biến thiên thì trong cuộn dây xuất hiện dòng điện cảm ứng.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Dòng điện xoay chiều khác dòng điện một chiều ở điểm cơ bản nào?","o":["Dòng điện xoay chiều không có cường độ","Dòng điện xoay chiều chỉ có trong pin","Dòng điện một chiều luân phiên đổi chiều liên tục","Dòng điện xoay chiều luân phiên đổi chiều, còn dòng điện một chiều không đổi chiều"],"a":"Dòng điện xoay chiều luân phiên đổi chiều, còn dòng điện một chiều không đổi chiều","h":"Điện lấy từ ổ cắm trong nhà thuộc loại nào và chiều của nó có thay đổi không?","e":"Dòng điện xoay chiều luân phiên đổi chiều theo thời gian (điện lưới sinh hoạt), còn dòng điện một chiều (từ pin, acquy) luôn giữ một chiều.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Máy phát điện xoay chiều ở nhà máy điện hoạt động dựa trên hiện tượng vật lí nào?","o":["Hiện tượng khúc xạ ánh sáng","Hiện tượng cảm ứng điện từ","Sự dẫn nhiệt của kim loại","Sự nhiễm điện do cọ xát"],"a":"Hiện tượng cảm ứng điện từ","h":"Bên trong máy phát điện có cuộn dây quay trong từ trường của nam châm.","e":"Máy phát điện xoay chiều biến cơ năng thành điện năng dựa trên hiện tượng cảm ứng điện từ: quay cuộn dây (hoặc nam châm) làm số đường sức từ qua cuộn dây biến thiên, sinh ra dòng điện xoay chiều.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Hiện tượng khúc xạ ánh sáng là hiện tượng:","o":["Tia sáng bị hắt trở lại môi trường cũ","Tia sáng bị môi trường hấp thụ hoàn toàn","Tia sáng bị gãy khúc tại mặt phân cách khi truyền từ môi trường trong suốt này sang môi trường trong suốt khác","Tia sáng tự đổi màu khi truyền đi"],"a":"Tia sáng bị gãy khúc tại mặt phân cách khi truyền từ môi trường trong suốt này sang môi trường trong suốt khác","h":"Hiện tượng này khiến chiếc đũa trong cốc nước trông như bị gãy ở mặt nước.","e":"Khi ánh sáng truyền qua mặt phân cách giữa hai môi trường trong suốt khác nhau (ví dụ không khí – nước), tia sáng bị gãy khúc tại mặt phân cách, gọi là hiện tượng khúc xạ ánh sáng.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Đặc điểm nào sau đây đúng với thấu kính hội tụ?","o":["Phần rìa mỏng hơn phần giữa và làm chùm tia sáng song song tới hội tụ tại một điểm","Phần giữa mỏng hơn phần rìa","Làm chùm tia sáng song song phân kì ra xa nhau","Chỉ có tác dụng như một tấm kính phẳng"],"a":"Phần rìa mỏng hơn phần giữa và làm chùm tia sáng song song tới hội tụ tại một điểm","h":"Kính lúp dùng để phóng to ảnh là một thấu kính hội tụ.","e":"Thấu kính hội tụ có phần rìa mỏng hơn phần giữa; chùm tia tới song song đi qua thấu kính sẽ hội tụ tại tiêu điểm, nên được dùng làm kính lúp, vật kính máy ảnh.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Nguồn năng lượng nào sau đây là năng lượng tái tạo?","o":["Năng lượng mặt trời","Than đá","Dầu mỏ","Khí đốt tự nhiên"],"a":"Năng lượng mặt trời","h":"Nguồn năng lượng tái tạo được bổ sung liên tục trong tự nhiên và khó cạn kiệt.","e":"Năng lượng mặt trời (cũng như gió, nước, địa nhiệt) là năng lượng tái tạo; than đá, dầu mỏ, khí đốt là nhiên liệu hoá thạch không tái tạo và sẽ cạn dần.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Vì sao mỗi người cần sử dụng năng lượng một cách tiết kiệm và hiệu quả?","o":["Vì năng lượng không cần thiết cho đời sống","Vì dùng nhiều điện sẽ làm hỏng mọi thiết bị ngay lập tức","Vì năng lượng tái tạo là nguồn gây ô nhiễm chính","Vì nhiên liệu hoá thạch có hạn và gây ô nhiễm môi trường; tiết kiệm năng lượng giúp giảm chi phí và bảo vệ môi trường"],"a":"Vì nhiên liệu hoá thạch có hạn và gây ô nhiễm môi trường; tiết kiệm năng lượng giúp giảm chi phí và bảo vệ môi trường","h":"Hãy nghĩ đến nguồn than, dầu đang cạn dần và khí thải khi đốt nhiên liệu.","e":"Sử dụng năng lượng tiết kiệm, hiệu quả giúp kéo dài nguồn nhiên liệu hoá thạch đang cạn kiệt, giảm phát thải khí nhà kính, bảo vệ môi trường và giảm chi phí cho gia đình, xã hội.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Vật chất di truyền ở cấp độ phân tử, lưu giữ thông tin quy định các tính trạng của cơ thể, là chất nào?","o":["Protein","Lipid (chất béo)","DNA","Tinh bột"],"a":"DNA","h":"Tên viết tắt này gồm ba chữ cái bắt đầu bằng D và nằm chủ yếu trong nhân tế bào.","e":"DNA là vật chất di truyền ở cấp độ phân tử, lưu giữ và truyền đạt thông tin di truyền qua các thế hệ tế bào và cơ thể.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Phân tử DNA có cấu trúc như thế nào?","o":["Gồm một mạch thẳng từ các amino acid","Gồm hai mạch xoắn kép, cấu tạo từ các đơn phân là nucleotide","Có dạng hình cầu rỗng","Gồm các đơn phân là glucose xếp thành vòng"],"a":"Gồm hai mạch xoắn kép, cấu tạo từ các đơn phân là nucleotide","h":"Hãy nhớ hình ảnh chiếc thang xoắn thường thấy trong sách sinh học.","e":"DNA cấu tạo từ các đơn phân nucleotide, gồm hai mạch polynucleotide xoắn kép ngược chiều, liên kết với nhau theo nguyên tắc bổ sung.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Gene được hiểu là:","o":["Toàn bộ tế bào","Một đoạn của phân tử DNA quy định một tính trạng nhất định của cơ thể","Một loại protein trong máu","Một cơ quan trong cơ thể"],"a":"Một đoạn của phân tử DNA quy định một tính trạng nhất định của cơ thể","h":"Mỗi tính trạng như màu mắt, nhóm máu... đều liên quan đến đơn vị di truyền này nằm trên DNA.","e":"Gene là một đoạn của phân tử DNA, mang thông tin quy định một tính trạng (hoặc cấu tạo một sản phẩm) nhất định của cơ thể.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Trong tế bào thường (tế bào sinh dưỡng) của người có bao nhiêu nhiễm sắc thể?","o":["46 nhiễm sắc thể (23 cặp)","23 nhiễm sắc thể","92 nhiễm sắc thể","44 nhiễm sắc thể"],"a":"46 nhiễm sắc thể (23 cặp)","h":"Số này là một số chẵn, gồm các cặp nhiễm sắc thể tương đồng.","e":"Tế bào sinh dưỡng của người có bộ nhiễm sắc thể lưỡng bội 2n = 46, gồm 23 cặp; còn giao tử chỉ có n = 23 nhiễm sắc thể.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Ứng dụng nào sau đây là ứng dụng của công nghệ gene?","o":["Lai hai giống lúa thuần chủng theo cách truyền thống","Ghép cành cam lên gốc bưởi","Chọn lọc cây tốt để làm giống qua nhiều vụ","Tạo giống cây trồng biến đổi gene cho năng suất cao, kháng sâu bệnh"],"a":"Tạo giống cây trồng biến đổi gene cho năng suất cao, kháng sâu bệnh","h":"Công nghệ này can thiệp trực tiếp vào vật chất di truyền của sinh vật.","e":"Công nghệ gene chuyển gene mong muốn vào sinh vật để tạo sinh vật biến đổi gene, ứng dụng trong nông nghiệp (cây kháng sâu, năng suất cao) và y học (sản xuất insulin).","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Kết quả của quá trình nguyên phân từ một tế bào mẹ là:","o":["Bốn tế bào con có bộ nhiễm sắc thể giảm một nửa","Một tế bào con duy nhất","Hai tế bào con có bộ nhiễm sắc thể giống hệt tế bào mẹ","Hai tế bào con có số nhiễm sắc thể gấp đôi tế bào mẹ"],"a":"Hai tế bào con có bộ nhiễm sắc thể giống hệt tế bào mẹ","h":"Nguyên phân giúp cơ thể lớn lên và thay thế tế bào già, chết nên bộ gene phải được giữ nguyên.","e":"Nguyên phân tạo ra 2 tế bào con có bộ nhiễm sắc thể giống hệt nhau và giống tế bào mẹ, giúp cơ thể sinh trưởng và tái tạo mô.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Quá trình giảm phân tạo ra các tế bào con có đặc điểm nào?","o":["Hai tế bào con giống hệt tế bào mẹ","Bốn tế bào con có bộ nhiễm sắc thể gấp đôi tế bào mẹ","Bốn tế bào con, mỗi tế bào có bộ nhiễm sắc thể giảm đi một nửa so với tế bào mẹ","Một tế bào con có đầy đủ bộ nhiễm sắc thể của mẹ"],"a":"Bốn tế bào con, mỗi tế bào có bộ nhiễm sắc thể giảm đi một nửa so với tế bào mẹ","h":"Giảm phân xảy ra khi hình thành giao tử để chuẩn bị cho thụ tinh.","e":"Giảm phân qua hai lần phân bào liên tiếp tạo 4 tế bào con có bộ nhiễm sắc thể đơn bội (n), bằng một nửa tế bào mẹ, làm tiền đề cho thụ tinh khôi phục bộ 2n ở hợp tử.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Loại tế bào nào sau đây ở người được tạo thành nhờ quá trình giảm phân?","o":["Tế bào da","Tế bào cơ tim","Tế bào thần kinh","Tế bào sinh dục (giao tử: tinh trùng và trứng)"],"a":"Tế bào sinh dục (giao tử: tinh trùng và trứng)","h":"Các tế bào này chỉ chứa một nửa số nhiễm sắc thể so với tế bào thường.","e":"Giảm phân xảy ra ở cơ quan sinh dục, tạo giao tử (tinh trùng, trứng) mang bộ nhiễm sắc thể đơn bội n = 23 ở người.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Biến dị là hiện tượng:","o":["Con sinh ra giống hệt bố mẹ về mọi tính trạng","Con sinh ra có những điểm khác biệt so với bố mẹ và so với nhau","Tế bào phân chia liên tục không ngừng","Sinh vật tăng kích thước theo thời gian"],"a":"Con sinh ra có những điểm khác biệt so với bố mẹ và so với nhau","h":"Nhờ hiện tượng này mà anh chị em ruột vẫn có nhiều nét khác nhau.","e":"Biến dị là những khác biệt về tính trạng giữa các cá thể con với bố mẹ và giữa các cá thể với nhau, tạo nên sự đa dạng của sinh giới.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Đột biến được hiểu là:","o":["Những biến đổi xảy ra trong vật chất di truyền (gene hoặc nhiễm sắc thể)","Sự thay đổi của môi trường sống quanh sinh vật","Sự tăng cơ bắp do luyện tập thể thao","Sự đổi màu da khi phơi nắng lâu ngày"],"a":"Những biến đổi xảy ra trong vật chất di truyền (gene hoặc nhiễm sắc thể)","h":"Loại biến đổi này có thể di truyền cho thế hệ sau vì liên quan đến bộ gene.","e":"Đột biến là những biến đổi trong vật chất di truyền ở cấp phân tử (gene) hoặc cấp tế bào (nhiễm sắc thể); đột biến có thể có hại, có lợi hoặc trung tính.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Bệnh Đao (hội chứng Down) ở người là do nguyên nhân nào?","o":["Tế bào của người bệnh thừa 1 nhiễm sắc thể ở cặp số 21 (có 3 nhiễm sắc thể số 21)","Tế bào thiếu hẳn cặp nhiễm sắc thể số 21","Nhiễm một loại vi khuẩn gây bệnh","Thiếu vitamin trong khẩu phần ăn"],"a":"Tế bào của người bệnh thừa 1 nhiễm sắc thể ở cặp số 21 (có 3 nhiễm sắc thể số 21)","h":"Đây là bệnh di truyền liên quan đến số lượng nhiễm sắc thể, không phải do nhiễm trùng hay dinh dưỡng.","e":"Bệnh Đao là đột biến số lượng nhiễm sắc thể: người bệnh có 47 nhiễm sắc thể do thừa 1 chiếc ở cặp 21, gây chậm phát triển trí tuệ và một số dị tật bẩm sinh.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Vì sao hôn nhân giữa những người có quan hệ huyết thống gần (cận huyết) làm tăng nguy cơ bệnh di truyền ở con?","o":["Vì con của họ luôn có thêm nhiễm sắc thể","Vì bố mẹ gần huyết thống dễ mang cùng gene lặn gây bệnh, khi kết hợp ở con sẽ biểu hiện thành bệnh","Vì máu của bố mẹ giống nhau nên con yếu hơn","Vì họ thường sống chung một môi trường ô nhiễm"],"a":"Vì bố mẹ gần huyết thống dễ mang cùng gene lặn gây bệnh, khi kết hợp ở con sẽ biểu hiện thành bệnh","h":"Nhiều gene gây bệnh là gene lặn, chỉ biểu hiện khi có mặt cả hai bản sao từ bố và mẹ.","e":"Người cùng huyết thống có hệ gene giống nhau nhiều, dễ cùng mang gene lặn có hại; con nhận cả hai gene lặn từ bố và mẹ sẽ mắc bệnh di truyền, nên pháp luật cấm kết hôn cận huyết.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Theo học thuyết tiến hoá của Đac-uyn, chọn lọc tự nhiên diễn ra như thế nào?","o":["Mọi cá thể trong quần thể đều sống sót và sinh sản như nhau","Sinh vật tự thay đổi cơ thể theo ý muốn để thích nghi","Con người chọn những cá thể tốt nhất để nhân giống","Các cá thể có đặc điểm thích nghi tốt hơn với môi trường sẽ sống sót và sinh sản nhiều hơn, truyền lại đặc điểm đó cho đời sau"],"a":"Các cá thể có đặc điểm thích nghi tốt hơn với môi trường sẽ sống sót và sinh sản nhiều hơn, truyền lại đặc điểm đó cho đời sau","h":"Đac-uyn quan sát thấy số con sinh ra nhiều hơn số con sống sót đến tuổi sinh sản rất nhiều.","e":"Chọn lọc tự nhiên: trong cuộc đấu tranh sinh tồn, cá thể mang đặc điểm thích nghi tốt hơn có khả năng sống sót và sinh sản cao hơn, qua nhiều thế hệ quần thể dần thích nghi với môi trường.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Bằng chứng nào sau đây là bằng chứng trực tiếp, quan trọng về lịch sử tiến hoá của sinh giới?","o":["Truyện cổ tích về nguồn gốc loài người","Ý kiến chủ quan của một cá nhân","Hoá thạch của các sinh vật cổ được lưu giữ trong các lớp đất đá","Bức ảnh chụp một loài vật hiện nay"],"a":"Hoá thạch của các sinh vật cổ được lưu giữ trong các lớp đất đá","h":"Loại bằng chứng này cho thấy hình ảnh thật của sinh vật từng sống trong quá khứ xa xưa.","e":"Hoá thạch là di tích của sinh vật cổ được bảo tồn trong đất đá, là bằng chứng trực tiếp ghi lại quá trình tiến hoá; ngoài ra còn có bằng chứng so sánh cấu tạo cơ quan giữa các loài.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Hiện tượng phản xạ toàn phần xảy ra khi ánh sáng truyền:","o":["Từ môi trường chiết quang hơn sang môi trường chiết quang kém hơn, với góc tới đủ lớn","Từ môi trường chiết quang kém hơn sang môi trường chiết quang hơn","Vuông góc với mặt phân cách giữa hai môi trường","Từ chân không vào bất kì môi trường nào"],"a":"Từ môi trường chiết quang hơn sang môi trường chiết quang kém hơn, với góc tới đủ lớn","h":"Điều kiện cần: ánh sáng đi từ môi trường 'đặc' hơn về quang học sang môi trường 'loãng' hơn.","e":"Phản xạ toàn phần chỉ xảy ra khi ánh sáng đi từ môi trường chiết quang hơn sang môi trường chiết quang kém hơn và góc tới lớn hơn góc tới giới hạn; hiện tượng này được ứng dụng trong cáp quang.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Khi chiếu một chùm ánh sáng trắng qua một lăng kính, ta thu được:","o":["Một chùm sáng trắng sáng mạnh hơn","Một dải màu liên tục từ đỏ đến tím","Chỉ hai màu đỏ và tím","Chùm sáng bị lăng kính hấp thụ hết"],"a":"Một dải màu liên tục từ đỏ đến tím","h":"Hiện tượng này cũng là nguyên nhân tạo nên cầu vồng sau mưa.","e":"Lăng kính làm tán sắc ánh sáng trắng thành dải màu liên tục: đỏ, da cam, vàng, lục, lam, chàm, tím, vì mỗi ánh sáng màu bị lệch đi một góc khác nhau.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Kính lúp dùng để quan sát các vật nhỏ là một:","o":["Thấu kính phân kì có tiêu cự dài","Gương phẳng nhỏ cầm tay","Thấu kính hội tụ có tiêu cự ngắn","Lăng kính bằng thuỷ tinh"],"a":"Thấu kính hội tụ có tiêu cự ngắn","h":"Kính lúp cho ảnh lớn hơn vật nên phải là thấu kính hội tụ.","e":"Kính lúp là thấu kính hội tụ có tiêu cự ngắn (thường không quá 25 cm); khi đặt vật trong khoảng tiêu cự, kính cho ảnh ảo cùng chiều, lớn hơn vật.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Một điện trở R = 6 Ω được mắc vào hiệu điện thế U = 12 V. Theo định luật Ohm (I = U/R), cường độ dòng điện chạy qua điện trở là:","o":["0,5 A","72 A","18 A","2 A"],"a":"2 A","h":"Áp dụng trực tiếp công thức I = U/R rồi thay số.","e":"I = U/R = 12/6 = 2 A.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Trong đoạn mạch gồm hai bóng đèn mắc nối tiếp, cường độ dòng điện tại mọi điểm trong mạch:","o":["Bằng nhau tại mọi điểm","Lớn nhất ở bóng đèn gần cực dương nhất","Nhỏ dần từ đầu mạch đến cuối mạch","Bằng tổng cường độ qua hai bóng đèn"],"a":"Bằng nhau tại mọi điểm","h":"Mạch nối tiếp chỉ có một lối đi duy nhất cho dòng điện.","e":"Trong đoạn mạch mắc nối tiếp, cường độ dòng điện tại mọi điểm đều bằng nhau: I = I1 = I2, còn hiệu điện thế hai đầu đoạn mạch bằng tổng hiệu điện thế trên từng bóng đèn.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Một bóng đèn hoạt động với hiệu điện thế 220 V và cường độ dòng điện qua đèn là 0,5 A. Công suất điện của bóng đèn (P = U·I) là:","o":["55 W","110 W","220 W","440 W"],"a":"110 W","h":"Nhân hiệu điện thế với cường độ dòng điện.","e":"P = U·I = 220 × 0,5 = 110 W.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Dòng điện xoay chiều có thể gây ra những tác dụng nào sau đây?","o":["Chỉ có tác dụng hoá học","Chỉ có tác dụng sinh lí","Có tác dụng nhiệt, tác dụng từ và tác dụng phát sáng","Không gây ra tác dụng nào"],"a":"Có tác dụng nhiệt, tác dụng từ và tác dụng phát sáng","h":"Hãy kể tên các thiết bị điện trong nhà đang dùng dòng điện xoay chiều.","e":"Dòng điện xoay chiều có tác dụng nhiệt (bàn là, ấm điện), tác dụng từ (nam châm điện của cần cẩu), tác dụng phát sáng (bóng đèn); ngoài ra còn có tác dụng sinh lí và hoá học.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Nhiên liệu hoá thạch như than đá, dầu mỏ, khí tự nhiên thuộc loại năng lượng nào?","o":["Năng lượng tái tạo, sạch và vô tận","Năng lượng tái tạo nhưng khó khai thác","Năng lượng không thải ra khí nào khi đốt","Năng lượng không tái tạo, khi đốt thải ra nhiều CO2"],"a":"Năng lượng không tái tạo, khi đốt thải ra nhiều CO2","h":"Than và dầu mỏ phải mất hàng triệu năm mới hình thành được.","e":"Nhiên liệu hoá thạch hình thành qua hàng triệu năm nên dùng dần sẽ cạn (không tái tạo); khi đốt chúng thải ra CO2 gây hiệu ứng nhà kính.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Trong công nghiệp, các kim loại có mức độ hoạt động hoá học trung bình hoặc yếu (như iron, zinc, copper) thường được tách ra khỏi oxide của chúng bằng phương pháp nào?","o":["Nhiệt luyện: khử oxide kim loại bằng CO hoặc C ở nhiệt độ cao","Điện phân dung dịch muối của kim loại","Cho oxide kim loại tác dụng với nước lạnh","Ngâm oxide kim loại trong dầu mỏ"],"a":"Nhiệt luyện: khử oxide kim loại bằng CO hoặc C ở nhiệt độ cao","h":"Phương pháp này dùng chất khử như CO ở nhiệt độ cao.","e":"Kim loại hoạt động trung bình/yếu được điều chế bằng nhiệt luyện, ví dụ: Fe2O3 + 3CO → 2Fe + 3CO2. Chỉ các kim loại rất hoạt động (Na, Ca, Al...) mới phải dùng điện phân nóng chảy.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Phi kim khác kim loại chủ yếu ở điểm nào sau đây?","o":["Phi kim có ánh kim còn kim loại thì không","Phi kim thường không dẫn điện, dẫn nhiệt kém; kim loại dẫn điện, dẫn nhiệt tốt","Phi kim đều là chất lỏng ở điều kiện thường","Phi kim dễ dát mỏng và kéo sợi như kim loại"],"a":"Phi kim thường không dẫn điện, dẫn nhiệt kém; kim loại dẫn điện, dẫn nhiệt tốt","h":"Hãy so sánh tính dẫn điện, dẫn nhiệt của hai nhóm chất này.","e":"Kim loại dẫn điện, dẫn nhiệt tốt và có ánh kim; phi kim thường không dẫn điện, dẫn nhiệt kém (ngoại lệ: than chì dẫn điện được).","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Khi đốt cháy hoàn toàn một alkane (ví dụ methane CH4) trong khí oxygen, sản phẩm tạo thành là:","o":["Carbon monoxide (CO) và hydrogen (H2)","Carbon (C) và nước (H2O)","Carbon dioxide (CO2) và nước (H2O)","Chỉ có carbon dioxide (CO2)"],"a":"Carbon dioxide (CO2) và nước (H2O)","h":"Alkane chỉ chứa C và H; cháy hoàn toàn thì C tạo khí chứa C, H tạo chất chứa H.","e":"Alkane cháy hoàn toàn trong oxygen tạo CO2 và H2O, toả nhiều nhiệt: CH4 + 2O2 → CO2 + 2H2O.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Ethylene (C2H4) làm mất màu dung dịch bromine. Nguyên nhân là do ethylene:","o":["Là chất khí không màu","Tan rất tốt trong nước","Có mùi thơm đặc trưng","Có liên kết đôi, tham gia phản ứng cộng với bromine"],"a":"Có liên kết đôi, tham gia phản ứng cộng với bromine","h":"Hãy chú ý đặc điểm liên kết trong phân tử ethylene.","e":"Ethylene có liên kết đôi C=C nên tham gia phản ứng cộng với bromine: C2H4 + Br2 → C2H4Br2, làm dung dịch bromine mất màu — đây là phản ứng dùng để nhận biết alkene.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Ethylic alcohol (ethanol, C2H5OH) là chất:","o":["Cháy được, là thành phần chính của rượu, bia và cồn sát trùng","Không cháy, thường dùng để dập tắt đám cháy","Có tính acid mạnh, làm quỳ tím hoá đỏ","Là chất rắn, tan rất ít trong nước"],"a":"Cháy được, là thành phần chính của rượu, bia và cồn sát trùng","h":"Cồn sát trùng và rượu uống đều chứa chất này.","e":"Ethanol cháy trong không khí tạo CO2 và H2O, toả nhiệt; ethanol là thành phần chính của rượu, bia và cồn sát trùng y tế.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Lạm dụng rượu, bia trong thời gian dài gây hại chủ yếu cho những cơ quan nào của cơ thể?","o":["Chỉ gây hại cho da và mắt","Gây hại chủ yếu cho gan và hệ thần kinh","Chỉ gây hại cho răng và miệng","Không gây hại gì nếu uống đều mỗi ngày"],"a":"Gây hại chủ yếu cho gan và hệ thần kinh","h":"Cơ quan phải 'giải độc' rượu cho cơ thể là cơ quan nào?","e":"Uống nhiều rượu bia lâu dài gây viêm gan, xơ gan, tổn thương hệ thần kinh, giảm trí nhớ và nhiều bệnh khác; học sinh tuyệt đối không uống rượu, bia.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Acetic acid là thành phần chính tạo nên vị chua của:","o":["Nước mắm truyền thống","Nước ngọt có gas","Giấm ăn, với nồng độ khoảng 2–5%","Dầu ăn tinh luyện"],"a":"Giấm ăn, với nồng độ khoảng 2–5%","h":"Gia vị nào trong bếp có vị chua nhờ acid này?","e":"Giấm ăn là dung dịch acetic acid có nồng độ khoảng 2–5%. Acetic acid có tính acid nên làm quỳ tím hoá đỏ và tạo vị chua đặc trưng.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Chất béo (lipid) có vai trò quan trọng nào đối với cơ thể?","o":["Vận chuyển khí oxygen trong máu","Cấu tạo nên phân tử DNA","Tạo ra kháng thể chống lại bệnh tật","Là nguồn dự trữ năng lượng, có nhiều trong dầu, mỡ động vật và thực vật"],"a":"Là nguồn dự trữ năng lượng, có nhiều trong dầu, mỡ động vật và thực vật","h":"Nhóm chất này có nhiều trong dầu ăn, mỡ, bơ, lạc, vừng.","e":"Chất béo là nguồn dự trữ năng lượng lâu dài của cơ thể (1 g chất béo cung cấp khoảng 9 kcal), có nhiều trong mỡ động vật và dầu thực vật.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Glucose thuộc loại đường nào và có vai trò gì đối với tế bào?","o":["Là đường đơn, nguồn năng lượng trực tiếp cho tế bào","Là đường đôi, chỉ dùng để dự trữ lâu dài","Là một loại chất béo dự trữ năng lượng","Là thành phần cấu tạo nên protein"],"a":"Là đường đơn, nguồn năng lượng trực tiếp cho tế bào","h":"Đây là loại đường có trong máu và nhiều loại quả chín.","e":"Glucose là đường đơn, được tế bào hấp thụ trực tiếp và phân giải để giải phóng năng lượng cho mọi hoạt động sống.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Phát biểu nào sau đây đúng về tinh bột và cellulose?","o":["Cellulose bị thuỷ phân tạo glucose để cơ thể người hấp thụ","Tinh bột bị thuỷ phân tạo glucose; cellulose là thành phần chính của thành tế bào thực vật","Cả tinh bột và cellulose đều là các protein","Tinh bột chỉ có trong thịt và trứng"],"a":"Tinh bột bị thuỷ phân tạo glucose; cellulose là thành phần chính của thành tế bào thực vật","h":"Một chất bị thuỷ phân tạo glucose cho cơ thể; chất còn lại làm nên thành tế bào thực vật.","e":"Dưới tác dụng của enzyme hoặc acid, tinh bột bị thuỷ phân dần thành glucose để cơ thể hấp thụ. Cellulose cũng là polysaccharide nhưng là thành phần chính của thành tế bào thực vật và con người không tiêu hoá được.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Protein trong cơ thể được cấu tạo từ các đơn phân nào sau đây?","o":["Các phân tử glucose","Các acid béo và glycerol","Các amino acid","Các nucleotide"],"a":"Các amino acid","h":"Tên đơn phân này bắt đầu bằng từ 'amino'.","e":"Protein là polymer tự nhiên gồm nhiều amino acid liên kết với nhau; protein là thành phần cấu trúc quan trọng của tế bào (cơ, da, tóc...) và của các enzyme.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Polymer là hợp chất có đặc điểm nào sau đây?","o":["Có phân tử khối rất nhỏ, chỉ gồm vài nguyên tử","Chỉ tồn tại trong cơ thể sinh vật","Luôn ở trạng thái lỏng ở điều kiện thường","Có phân tử khối rất lớn, gồm nhiều mắt xích giống nhau lặp lại, ví dụ polyethylene"],"a":"Có phân tử khối rất lớn, gồm nhiều mắt xích giống nhau lặp lại, ví dụ polyethylene","h":"Phân tử polymer giống như một chuỗi dài gồm nhiều mắt xích giống nhau.","e":"Polymer là hợp chất có phân tử khối rất lớn, do nhiều mắt xích nhỏ giống nhau liên kết lặp lại tạo thành; ví dụ polyethylene (PE) dùng làm túi nylon, ống nhựa.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Đá vôi có thành phần chính là CaCO3, là nguyên liệu quan trọng để:","o":["Sản xuất xi măng và vôi","Sản xuất nhựa và cao su","Sản xuất thuỷ tinh và đồ gốm sứ","Sản xuất phân đạm"],"a":"Sản xuất xi măng và vôi","h":"Khi nung nóng, CaCO3 phân huỷ tạo ra vôi sống (CaO).","e":"Đá vôi (CaCO3) là nguyên liệu chính để sản xuất xi măng và nung thành vôi sống (CaO) dùng trong xây dựng.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Trong chu trình carbon, việc đốt nhiều nhiên liệu hoá thạch làm lượng CO2 trong khí quyển tăng lên, dẫn đến hậu quả nào sau đây?","o":["Làm Trái Đất lạnh dần đi","Làm tăng hiệu ứng nhà kính, khiến Trái Đất ấm lên","Làm tầng ozone dày lên","Không gây ảnh hưởng gì đến khí hậu"],"a":"Làm tăng hiệu ứng nhà kính, khiến Trái Đất ấm lên","h":"CO2 là một trong những khí nhà kính quan trọng nhất.","e":"CO2 là khí nhà kính: đốt than, dầu, khí tự nhiên làm CO2 trong khí quyển tăng, giữ nhiệt nhiều hơn khiến Trái Đất ấm lên và gây biến đổi khí hậu.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Quá trình tái bản (nhân đôi) của phân tử DNA cho kết quả là:","o":["Một phân tử DNA hoàn toàn khác DNA mẹ","Bốn phân tử DNA giống nhau","Hai phân tử DNA giống hệt phân tử DNA ban đầu","Một phân tử DNA và một phân tử protein"],"a":"Hai phân tử DNA giống hệt phân tử DNA ban đầu","h":"Quá trình này xảy ra trước khi tế bào phân chia.","e":"Trước khi tế bào phân chia, DNA được tái bản tạo thành hai phân tử DNA giống hệt nhau và giống DNA mẹ, đảm bảo thông tin di truyền được truyền đầy đủ cho các tế bào con.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Dịch mã là quá trình nào sau đây?","o":["Quá trình nhân đôi phân tử DNA","Quá trình tổng hợp mRNA từ khuôn DNA","Quá trình phân giải protein thành amino acid","Quá trình tổng hợp protein dựa trên thông tin của mRNA, diễn ra tại ribosome"],"a":"Quá trình tổng hợp protein dựa trên thông tin của mRNA, diễn ra tại ribosome","h":"Quá trình này tạo ra protein và diễn ra ở ribosome.","e":"Dịch mã diễn ra tại ribosome: thông tin di truyền trên mRNA được 'dịch' thành chuỗi amino acid tạo nên protein. Đây là một khâu trong dòng thông tin: gene → protein → tính trạng.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Đột biến gene được hiểu là:","o":["Biến đổi trong cấu trúc của gene, có thể di truyền cho thế hệ sau","Biến đổi về số lượng nhiễm sắc thể trong tế bào","Thay đổi kiểu hình do điều kiện môi trường thay đổi","Sự sắp xếp lại các gene trong quá trình giảm phân"],"a":"Biến đổi trong cấu trúc của gene, có thể di truyền cho thế hệ sau","h":"Loại đột biến này xảy ra ngay trong cấu trúc của gene.","e":"Đột biến gene là những biến đổi trong cấu trúc của gene (thêm, mất hoặc thay thế một hoặc một số cặp nucleotide); nếu xảy ra ở tế bào sinh dục, đột biến có thể di truyền cho đời sau.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Cặp nhiễm sắc thể giới tính ở người nữ và người nam lần lượt là:","o":["Nữ là XY, nam là XX","Nữ là XX, nam là XY","Cả nữ và nam đều là XX","Cả nữ và nam đều là XY"],"a":"Nữ là XX, nam là XY","h":"Người nữ thuộc giới đồng giao tử, người nam thuộc giới dị giao tử.","e":"Người nữ có cặp nhiễm sắc thể giới tính XX, người nam có XY. Trứng luôn mang nhiễm sắc thể X, còn tinh trùng mang X hoặc Y nên giới tính của con do tinh trùng của người bố quyết định.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Chọn lọc nhân tạo là quá trình:","o":["Môi trường tự nhiên giữ lại các cá thể thích nghi nhất","Các cá thể tự biến đổi để thích nghi với môi trường mới","Con người chọn giữ lại và cho sinh sản những cá thể có đặc điểm mong muốn","Đột biến xuất hiện ngẫu nhiên trong quần thể"],"a":"Con người chọn giữ lại và cho sinh sản những cá thể có đặc điểm mong muốn","h":"Quá trình này do con người chủ động thực hiện khi tạo giống cây trồng, vật nuôi.","e":"Chọn lọc nhân tạo là do con người thực hiện: chọn các cá thể có đặc điểm mong muốn (năng suất cao, chất lượng tốt) để làm giống. Khác với chọn lọc tự nhiên do điều kiện môi trường quyết định.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Cơ năng của một vật là gì, và điều gì xảy ra với cơ năng khi một vật rơi tự do (bỏ qua sức cản của không khí)?","o":["Hiệu của động năng và thế năng của vật","Tổng động năng và thế năng trọng trường của vật; khi vật rơi tự do bỏ qua ma sát, cơ năng không đổi","Chỉ bằng thế năng của vật","Chỉ bằng động năng của vật"],"a":"Tổng động năng và thế năng trọng trường của vật; khi vật rơi tự do bỏ qua ma sát, cơ năng không đổi","h":"Khi vật rơi, thế năng giảm thì động năng thay đổi thế nào?","e":"Cơ năng của một vật bằng tổng động năng và thế năng của nó. Khi một vật rơi tự do (bỏ qua sức cản của không khí), thế năng giảm dần và chuyển hoá thành động năng tăng dần, nhưng tổng cơ năng được bảo toàn, không đổi trong suốt quá trình rơi.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Phát biểu nào sau đây đúng về công suất cơ học?","o":["Công suất càng lớn khi công thực hiện được càng nhiều trong cùng một thời gian (P = A/t)","Công suất là tổng công cộng dồn của nhiều ngày làm việc","Công suất càng lớn khi vật di chuyển càng xa bất kể thời gian","Công suất được đo bằng đơn vị jun (J)"],"a":"Công suất càng lớn khi công thực hiện được càng nhiều trong cùng một thời gian (P = A/t)","h":"Công suất liên quan đến lượng công và thời gian thực hiện công đó.","e":"Công suất cho biết tốc độ thực hiện công: P = A/t. Cùng thực hiện một lượng công như nhau, ai hoàn thành trong thời gian ngắn hơn thì có công suất lớn hơn; đơn vị của công suất là oát (W).","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Các bóng đèn trong gia đình thường được mắc song song với nhau. Đặc điểm nào sau đây đúng với cách mắc này?","o":["Hiệu điện thế giữa hai đầu mỗi bóng đèn bằng hiệu điện thế của nguồn; tắt một đèn, các đèn còn lại vẫn sáng bình thường","Cường độ dòng điện chia đều qua các đèn nên đèn nào cũng tối đi một nửa","Tắt một bóng đèn thì tất cả các đèn khác đều tắt theo","Hiệu điện thế qua mỗi đèn cộng lại mới bằng hiệu điện thế nguồn"],"a":"Hiệu điện thế giữa hai đầu mỗi bóng đèn bằng hiệu điện thế của nguồn; tắt một đèn, các đèn còn lại vẫn sáng bình thường","h":"Hãy nghĩ về các bóng đèn trong nhà em: tắt đèn phòng khách, đèn phòng ngủ có tắt theo không?","e":"Trong đoạn mạch mắc song song, hai đầu mỗi nhánh đều nối trực tiếp với nguồn nên hiệu điện thế ở mỗi bóng đèn bằng hiệu điện thế của nguồn, và mỗi đèn hoạt động độc lập: ngắt một nhánh, các nhánh khác vẫn có điện. Vì vậy, các đồ điện trong nhà thường được mắc song song.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Loại đường nào được lấy chủ yếu từ cây mía và củ cải đường, là đường ăn quen thuộc trong đời sống?","o":["Glucose","Saccharose (đường mía, đường ăn hằng ngày)","Cellulose","Tinh bột"],"a":"Saccharose (đường mía, đường ăn hằng ngày)","h":"Hãy nghĩ đến loại đường trắng làm từ cây mía dùng trong bếp mỗi ngày.","e":"Saccharose là đường đôi, có nhiều trong cây mía, củ cải đường và quả thốt nốt; đây chính là đường ăn dùng hằng ngày. Còn glucose là đường đơn, có trong quả chín và trong máu người.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Hai nguyên tố hoá học chiếm tỉ lệ khối lượng lớn nhất trong vỏ Trái Đất là:","o":["Iron (sắt) và aluminium (nhôm)","Oxygen và silicon","Carbon và hydrogen","Nitrogen và oxygen"],"a":"Oxygen và silicon","h":"Hãy nhớ vỏ Trái Đất chứa rất nhiều hợp chất của oxygen và silicon (như cát, đá, đất).","e":"Trong vỏ Trái Đất, oxygen chiếm tỉ lệ khối lượng lớn nhất (khoảng 46–47%), tiếp theo là silicon (khoảng 27–28%). Hai nguyên tố này chiếm gần ba phần tư khối lượng vỏ Trái Đất; tiếp sau là nhôm, sắt, calcium...","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Trong thí nghiệm lai của Mendel, tính trạng trội là:","o":["Tính trạng chỉ xuất hiện ở đời cháu F2","Tính trạng được biểu hiện ngay ở đời con lai F1 khi lai hai cơ thể thuần chủng khác nhau về tính trạng đó","Tính trạng do môi trường tạo ra cho cơ thể","Tính trạng chỉ có ở cơ thể bố"],"a":"Tính trạng được biểu hiện ngay ở đời con lai F1 khi lai hai cơ thể thuần chủng khác nhau về tính trạng đó","h":"Trong thí nghiệm của Mendel, F1 toàn hoa đỏ khi lai cây hoa đỏ thuần chủng với cây hoa trắng.","e":"Mendel lai đậu Hà Lan thuần chủng hoa đỏ với hoa trắng (hai tính trạng đối lập), đời F1 thu được toàn cây hoa đỏ. Tính trạng xuất hiện ngay ở F1 được gọi là tính trạng trội, còn tính trạng tạm ẩn đi (hoa trắng) gọi là tính trạng lặn.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Mendel cho các cây đậu Hà Lan F1 (đều hoa đỏ, sinh ra từ phép lai cây hoa đỏ thuần chủng với cây hoa trắng) tự thụ phấn. Tỉ lệ kiểu hình ở đời F2 xấp xỉ là:","o":["Toàn bộ là hoa đỏ","Khoảng 3 cây hoa đỏ : 1 cây hoa trắng","Khoảng 1 cây hoa đỏ : 1 cây hoa trắng","Toàn bộ là hoa trắng"],"a":"Khoảng 3 cây hoa đỏ : 1 cây hoa trắng","h":"Tính trạng lặn không mất hẳn mà xuất hiện lại ở F2 với tỉ lệ 1/4.","e":"Khi cho F1 (toàn hoa đỏ) tự thụ phấn, ở F2 tính trạng lặn (hoa trắng) xuất hiện trở lại với tỉ lệ kiểu hình xấp xỉ 3 trội : 1 lặn (3 hoa đỏ : 1 hoa trắng). Đây là kết quả nổi tiếng trong thí nghiệm lai một cặp tính trạng của Mendel.","t":"khtn-lop9","g":9,"l":"thu-thach"},{"p":"Vì sao một số tính trạng thường được di truyền cùng nhau qua nhiều thế hệ (hiện tượng di truyền liên kết)?","o":["Vì các gene đó nằm trên cùng một nhiễm sắc thể nên có xu hướng cùng được truyền cho đời con","Vì các gene đó luôn nằm ở các tế bào khác nhau","Vì môi trường ép các tính trạng phải giống nhau","Vì các gene tự sao chép lẫn nhau"],"a":"Vì các gene đó nằm trên cùng một nhiễm sắc thể nên có xu hướng cùng được truyền cho đời con","h":"Nhiễm sắc thể là cấu trúc mang nhiều gene cùng lúc.","e":"Các gene nằm trên cùng một nhiễm sắc thể tạo thành một nhóm gene liên kết và có xu hướng di truyền cùng nhau qua các thế hệ. Hiện tượng di truyền liên kết được nhà di truyền học Morgan phát hiện qua thí nghiệm trên ruồi giấm.","t":"khtn-lop9","g":9,"l":"nhe-nhang"},{"p":"Theo quan điểm khoa học về sự phát sinh sự sống trên Trái Đất, phát biểu nào sau đây đúng?","o":["Sự sống được đưa tới Trái Đất nguyên vẹn từ một hành tinh khác","Sự sống đầu tiên xuất hiện trong môi trường nước (các đại dương nguyên thuỷ) từ các chất vô cơ qua quá trình tiến hoá hoá học lâu dài","Các loài sinh vật hiện nay xuất hiện cùng một lúc ngay từ khi Trái Đất hình thành","Sự sống đầu tiên xuất hiện trên mặt đất khô cằn"],"a":"Sự sống đầu tiên xuất hiện trong môi trường nước (các đại dương nguyên thuỷ) từ các chất vô cơ qua quá trình tiến hoá hoá học lâu dài","h":"Sinh vật đầu tiên là những sinh vật đơn bào sống trong nước.","e":"Theo khoa học hiện nay, khoảng 3,5–4 tỉ năm trước, từ các chất vô cơ trong khí quyển và đại dương nguyên thuỷ, dưới tác động của tia tử ngoại và sấm sét, đã hình thành các chất hữu cơ đơn giản, rồi dần tiến hoá thành các tế bào sống đầu tiên trong nước.","t":"khtn-lop9","g":9,"l":"nhe-nhang"}];